                { key: "actions", label: this.$t("actions") || "الإجراءات", class: "text-center" },
            );
            return fields;
        },
        creditSettlementsTableFields() {
            return [
                { key: "orderCode", label: this.$t("invoice_number") || "الفاتورة", sortable: true },
                { key: "customerName", label: this.$t("customerName") || "الزبون", sortable: true },
                { key: "amount", label: this.$t("amount") || "المبلغ", sortable: true },
                { key: "paymentMethod", label: this.$t("paymentMethod") || "طريقة التحصيل", sortable: true },
                { key: "insertDate", label: this.$t("date") || "التاريخ", sortable: true },
                { key: "notes", label: this.$t("notes") || "ملاحظات", sortable: false },
            ];
        },
        hasActiveFilters() {
            return !!(
                this.search.info ||
                this.search.startDate ||
                this.search.endDate ||
                this.search.paymentMethod ||
                this.search.orderSource ||
                this.search.brandId
            );
        },
        hasAdvancedFilters() {
            return !!(
                this.reportFilters.startDate ||
                this.reportFilters.endDate ||
                this.reportBrandId ||
                (this.activeTab === "productSales" &&
                    (this.productSalesFilters.tag ||
                        (this.productSalesFilters.info || "").trim())) ||
                (this.activeTab === "financialOps" &&
                    (this.financialOpsSelectedCategories || []).length)
            );
        },
        hasReportFilters() {
            if (this.activeTab === "orders") return this.hasActiveFilters;
            if (this.activeTab === "lowStock") {
                return Number(this.lowStockThreshold) !== 10 || !!this.reportBrandId;
            }
            if (this.activeTab === "expiry") {
                return Number(this.expiryDaysWithin) !== 30 || !!this.reportBrandId;
            }
            if (this.activeTab === "inventoryValue") {
                return !!(
                    this.reportBrandId ||
                    this.inventoryValueFilters.tag ||
                    (this.inventoryValueFilters.info || "").trim()
                );
            }
            return this.hasAdvancedFilters;
        },
        reportsFiltersHint() {
            const map = {
                orders: this.$t("ordersFiltersHint") || "تصفية الفواتير بالتاريخ أو طريقة الدفع أو رقم الفاتورة",
                profit: this.$t("dateFiltersHint") || "حدد فترة التقرير",
                financialOps:
                    this.$t("financialOpsFiltersHint") ||
                    "حدد الفترة واختر فئات المصروف لحساب صافي الأرباح",
                topItems: this.$t("dateFiltersHint") || "حدد فترة التقرير",
                productSales: this.$t("productSalesFiltersHint") || "فلترة حسب التاريخ والقسم واسم المنتج",
                byCategory: this.$t("dateFiltersHint") || "حدد فترة التقرير",
                byEmployee: this.$t("dateFiltersHint") || "حدد فترة التقرير",
                byWarehouse: this.$t("dateFiltersHint") || "حدد فترة التقرير",
                lowStock: this.$t("lowStockFiltersHint") || "حد الكمية لعرض المنتجات القليلة أو المنتهية",
                expiry: this.$t("expiryFiltersHint") || "أدخل عدد الأيام لعرض المنتهية أو القريبة من الانتهاء",
                inventoryValue:
                    this.$t("inventoryValuationFiltersHint") ||
                    "فلترة حسب البراند أو القسم أو اسم المنتج",
            };
            return map[this.activeTab] || (this.$t("filters") || "فلاتر التقرير");
        },
        financialOpsCategoryFields() {
            return [
                {
                    key: "category",
                    label: this.$t("expenseCategory") || this.$t("category") || "الفئة",
                },
                {
                    key: "totalAmount",
                    label: this.$t("totalAmount") || "المبلغ",
                },
                {
                    key: "count",
                    label: this.$t("count") || "العدد",
                },
            ];
        },
        expiredItemsCount() {
            return (this.expiringItems || []).filter((i) => i.status === "expired" || Number(i.daysRemaining) < 0).length;
        },
        expiringSoonItemsCount() {
            return (this.expiringItems || []).filter((i) => i.status === "expiring" || Number(i.daysRemaining) >= 0).length;
        },
        formattedNumber() {
            return formatMoney(this.totaPrice);
        },
        reportInvoiceItemCount() {
            return (this.customerOrderItem || []).reduce(
                (sum, item) => sum + (Number(item.quantity) || 0),
                0
            );
        },
        orderEmployeeName() {
            return (
                this.order?.createdByUsername ||
                this.userInfo?.name ||
                this.userInfo?.fullName ||
                '—'
            );
        },

        customerOrderItemField() {
            const lang = this.$i18n.locale
            if (!lang) { return [] }
            return [
                {
                    key: "item.name",
                    label: this.$i18n.t('item_name_label'),
                },
                {
                    key: "item.purchasingPrice",
                    label: this.$i18n.t('purchase_price_label'),
                },
                {
                    key: "item.sellingPrice",
                    label: this.$i18n.t('selling_price_label'),
                },
                {
                    key: "quantity",
                    label: this.$i18n.t('quantity_label'),
                },
                {
                    key: "totalPrice",
                    label: this.$i18n.t('total_label'),
                },

            ];
        },

        customerOrderItemsWithTotalPrice() {
            return this.customerOrderItem.map(item => {
                const sellingPrice = this.getSellingPrice(item);
                return {
                    ...item,
                    totalPrice: item.quantity * sellingPrice,
                };
            });
        },
        editOrderTotal() {
            return this.editOrderForm.items.reduce((sum, item) => sum + (item.price || 0) * (item.quantity || 0), 0);
        },
        editOrderDiscountAmount() {
            const rawValue = Number(this.editOrderForm.discountValue) || 0;
            if (!this.editOrderForm.discountType || rawValue <= 0) return 0;
            if (this.editOrderForm.discountType === 'percentage') {
                return Math.min(this.editOrderTotal, (this.editOrderTotal * Math.min(rawValue, 100)) / 100);
            }
            return Math.min(this.editOrderTotal, rawValue);
        },
        editOrderFinalTotal() {
            return Math.max(this.editOrderTotal - this.editOrderDiscountAmount, 0);
        },
        editOrderDiscountPreviewLabel() {
            if (!this.editOrderForm.discountType || !(Number(this.editOrderForm.discountValue) > 0)) {
                return this.$t("noDiscount") || "بدون خصم";
            }
            if (this.editOrderForm.discountType === "percentage") {
                return `${Math.min(Number(this.editOrderForm.discountValue) || 0, 100)}%`;
            }
            return `${this.formatPrice(this.editOrderForm.discountValue)} ${this.$t("currency")}`;
        },
    },
    watch: {
        customerOrderItem: {
            handler() {
                this.totaPrice = 0;
                this.customerOrderItem.forEach((item) => {
                    const sellingPrice = this.getSellingPrice(item);
                    this.totaPrice += item.quantity * sellingPrice;
                });
            },
            deep: true,
        },
        search: {
            handler() {
                if (this.skipOrdersSearchWatch) return;

                if (this.searchTimer) {
                    clearTimeout(this.searchTimer);
                }

                // Reset to first page without triggering a second fetch via pageNumber watcher.
                if (this.pageNumber !== 1) {
                    this.skipOrdersPageWatch = true;
                    this.pageNumber = 1;
                }

                this.searchTimer = setTimeout(() => {
                    this.GetAllOrders();
                }, 500);
            },
            deep: true,
        },

        pageNumber() {
            if (this.skipOrdersPageWatch) {
                this.skipOrdersPageWatch = false;
                return;
            }
            this.GetAllOrders();
        },
        activeTab(tab) {
            if (tab !== "orders" && this.secretDeleteMode) {
                this.exitSecretDeleteMode();
            }
        },
    },

    mounted() {
        this.ensureReportBrands();
        this.GetAllOrders();
        this.userInfo = JSON.parse(localStorage.getItem('info'));
        this.loadCommercialUserInfo();
        this.loadManagedPrinters();
        window.addEventListener("keydown", this.onSecretDeleteKeydown);
    },
    
    beforeDestroy() {
        // Clear search timer to prevent memory leaks
        if (this.searchTimer) {
            clearTimeout(this.searchTimer);
        }
        if (this.expiryFilterTimer) {
            clearTimeout(this.expiryFilterTimer);
        }
        window.removeEventListener("keydown", this.onSecretDeleteKeydown);
    },

    methods: {
        onSecretDeleteKeydown(event) {
            if (!this.canSecretDeleteOrders) return;
            if (this.activeTab !== "orders") return;
            const tag = String(event?.target?.tagName || "").toLowerCase();
            if (tag === "input" || tag === "textarea" || tag === "select" || event?.target?.isContentEditable) {
                return;
            }
            if (event.key === "Escape" && this.secretDeleteMode) {
                this.exitSecretDeleteMode();
                return;
            }
            if (!/^[0-9]$/.test(event.key)) {
                this.secretKeyBuffer = "";
                return;
            }
            const next = (this.secretKeyBuffer + event.key).slice(-6);
            this.secretKeyBuffer = next;
            if (next === "123321") {
                this.secretKeyBuffer = "";
                this.enterSecretDeleteMode();
            }
        },
        enterSecretDeleteMode() {
            if (this.secretDeleteMode) return;
            this.secretDeleteMode = true;
            this.selectedOrderIds = [];
            this.$notify?.info?.(this.$t("secretDeleteModeOn") || "تم تفعيل وضع مسح الفواتير", {
                position: "top-right",
                timeout: 2500,
                maxToasts: 1,
            });
        },
        exitSecretDeleteMode() {
            this.secretDeleteMode = false;
            this.selectedOrderIds = [];
            this.secretKeyBuffer = "";
        },
        isOrderSelected(id) {
            return this.selectedOrderIds.includes(id);
        },
        toggleOrderSelection(id, checked) {
            if (checked) {
                if (!this.selectedOrderIds.includes(id)) {
                    this.selectedOrderIds = this.selectedOrderIds.concat([id]);
                }
                return;
            }
            this.selectedOrderIds = this.selectedOrderIds.filter((x) => x !== id);
        },
        toggleSelectAllPage(checked) {
            const pageIds = this.Orders.map((o) => o.id);
            if (checked) {
                const set = new Set(this.selectedOrderIds.concat(pageIds));
                this.selectedOrderIds = Array.from(set);
                return;
            }
            this.selectedOrderIds = this.selectedOrderIds.filter((id) => !pageIds.includes(id));
        },
        async deleteSingleOrder(order) {
            if (!order?.id || this.deletingOrders) return;
            const ok = await this.$confirm({
                title: this.$t("confirmDelete") || "تأكيد الحذف",
                message:
                    this.$t("confirmDeleteInvoice", { code: order.orderCode || order.id }) ||
                    `هل تريد مسح الفاتورة ${order.orderCode || order.id}؟ سيتم إرجاع الكميات للمخزون.`,
                confirmText: this.$t("delete") || "مسح",
                cancelText: this.$t("cancel") || "إلغاء",
                variant: "danger",
            });
            if (!ok) return;
            await this.runDeleteOrders([order.id]);
        },
        async deleteSelectedOrders() {
            if (!this.selectedOrderIds.length || this.deletingOrders) return;
            const count = this.selectedOrderIds.length;
            const ok = await this.$confirm({
                title: this.$t("confirmDelete") || "تأكيد الحذف",
                message:
                    this.$t("confirmDeleteInvoices", { count }) ||
                    `هل تريد مسح ${count} فاتورة؟ سيتم إرجاع الكميات للمخزون.`,
                confirmText: this.$t("delete") || "مسح",
                cancelText: this.$t("cancel") || "إلغاء",
                variant: "danger",
            });
            if (!ok) return;
            await this.runDeleteOrders(this.selectedOrderIds.slice());
        },
        async runDeleteOrders(ids) {
            if (!ids?.length || this.deletingOrders) return;
            this.deletingOrders = true;
            try {
                const response = await HTTP.post("Admin/DeleteOrders", { ids });
                if (response?.data?.errorStatus) {
                    throw new Error(response.data.message || "orderDeleteFailed");
                }
                const deletedCount = response?.data?.data?.deletedCount ?? ids.length;
                this.$notify.success(
                    this.$t("invoicesDeleted", { count: deletedCount }) ||
                        `تم مسح ${deletedCount} فاتورة`,
                    { position: "top-right", timeout: 3000, maxToasts: 1 }
                );
                this.selectedOrderIds = [];
                this.GetAllOrders();
            } catch (error) {
                const msg = error?.response?.data?.message || error?.message;
                this.$notify.error(
                    (msg && this.$te(msg) ? this.$t(msg) : null) ||
                        this.$t("orderDeleteFailed") ||
                        "فشل مسح الفواتير",
                    { position: "top-right", timeout: 4000, maxToasts: 1 }
                );
            } finally {
                this.deletingOrders = false;
            }
        },
        formatReportPeriod(start, end) {
            if (start && end) return `${start} — ${end}`;
            if (start) return `${this.$t("from_date")}: ${start}`;
            if (end) return `${this.$t("to_date")}: ${end}`;
            return "";
        },
        refreshReports() {
            if (this.activeTab === "orders") {
                this.GetAllOrders();
            } else if (this.activeTab === "lowStock") {
                this.loadLowStockItems();
            } else if (this.activeTab === "expiry") {
                this.loadExpiringItems();
            } else if (this.activeTab === "inventoryValue") {
                this.loadInventoryValuationReport();
            } else {
                this.loadAdvancedReport();
            }
        },
        clearFilters() {
            if (this.searchTimer) {
                clearTimeout(this.searchTimer);
                this.searchTimer = null;
            }
            this.skipOrdersSearchWatch = true;
            this.skipOrdersPageWatch = this.pageNumber !== 1;
            this.search = {
                info: "",
                startDate: "",
                endDate: "",
                paymentMethod: "",
                orderSource: "",
                brandId: "",
            };
            this.pageNumber = 1;
            this.$nextTick(() => {
                this.skipOrdersSearchWatch = false;
            });
            this.GetAllOrders();
        },
        clearAdvancedFilters() {
            this.reportFilters = {
                startDate: "",
                endDate: "",
            };
            this.reportBrandId = "";
            this.productSalesFilters = {
                tag: "",
                info: "",
            };
            this.financialOpsSelectedCategories = [];
            this.loadAdvancedReport();
        },
        clearCurrentTabFilters() {
            if (this.activeTab === "orders") {
                this.clearFilters();
                return;
            }
            if (this.activeTab === "lowStock") {
                this.lowStockThreshold = 10;
                this.reportBrandId = "";
                this.loadLowStockItems();
                return;
            }
            if (this.activeTab === "expiry") {
                this.expiryDaysWithin = 30;
                this.reportBrandId = "";
                this.loadExpiringItems();
                return;
            }
            if (this.activeTab === "inventoryValue") {
                this.reportBrandId = "";
                this.inventoryValueFilters = { tag: "", info: "" };
                this.loadInventoryValuationReport();
                return;
            }
            this.clearAdvancedFilters();
        },
        ensureReportTags() {
            if (this.reportTags.length) return;
            HTTP.get("Admin/GetTags?pageNumber=0&pageSize=10000")
                .then((response) => {
                    this.reportTags = response.data?.data?.items || [];
                })
                .catch(() => {
                    this.reportTags = [];
                });
        },
        ensureReportBrands() {
            if (this.reportBrands.length) return;
            HTTP.get("Admin/GetBrands?pageNumber=0&pageSize=10000")
                .then((response) => {
                    this.reportBrands = response.data?.data?.items || [];
                })
                .catch(() => {
                    this.reportBrands = [];
                });
        },
        appendBrandIdParam(params, brandId) {
            if (brandId) params.append("brandId", String(brandId));
        },
        hasDiscount(item) {
            if (this.order?.isWholesale) return false;
            return item.item && 
                   item.item.disCountPrice && 
                   item.item.disCountPrice > 0 && 
                   item.item.disCountPrice !== item.item.sellingPrice &&
                   Number(item.sellingPrice) === Number(item.item.disCountPrice);
        },
        getSellingPrice(item) {
            if (item.sellingPrice != null && item.sellingPrice !== undefined) {
                return Number(item.sellingPrice) || 0;
            }
            if (this.hasDiscount(item)) {
                return item.item.disCountPrice;
            }
            return item.item?.sellingPrice || 0;
        },
        getRankClass(index) {
            if (index === 0) return 'rank-gold';
            if (index === 1) return 'rank-silver';
            if (index === 2) return 'rank-bronze';
            return '';
        },
        getStockStatusClass(item) {
            if (item.currentQuantity === 0) return 'status-out';
            if (item.currentQuantity <= item.threshold) return 'status-low';
            return 'status-ok';
        },
        getStockStatusIcon(item) {
            if (item.currentQuantity === 0) return 'x-circle-fill';
            if (item.currentQuantity <= item.threshold) return 'exclamation-triangle-fill';
            return 'check-circle-fill';
        },
        getStockStatusText(item) {
            if (item.currentQuantity === 0) return this.$t('outOfStock') || 'منتهي';
            if (item.currentQuantity <= item.threshold) return this.$t('lowStock') || 'قليل';
            return this.$t('inStock') || 'متوفر';
        },
        formatExpiryDate(value) {
            if (value == null || value === "") return "-";
            const s = String(value);
            if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
            const d = new Date(s);
            if (Number.isNaN(d.getTime())) return s;
            const yyyy = d.getFullYear();
            const mm = String(d.getMonth() + 1).padStart(2, "0");
            const dd = String(d.getDate()).padStart(2, "0");
            return `${yyyy}-${mm}-${dd}`;
        },
        getExpiryStatusClass(item) {
            if (item?.status === "expired" || Number(item?.daysRemaining) < 0) return "status-out";
            return "status-low";
        },
        getExpiryStatusIcon(item) {
            if (item?.status === "expired" || Number(item?.daysRemaining) < 0) return "x-circle-fill";
            return "hourglass-split";
        },
        getExpiryStatusText(item) {
            if (item?.status === "expired" || Number(item?.daysRemaining) < 0) {
                return this.$t("expiredStatus") || "منتهية";
            }
            return this.$t("expiringSoonStatus") || "قريبة من الانتهاء";
        },
        getPaymentMethodText(method) {
            if (!method) return '-';
            const methods = {
                'Cash': this.$t('cash') || 'نقدي',
                'Card': this.$t('card') || 'بطاقة',
                'Credit': this.$t('credit') || 'آجل',
                'BankTransfer': this.$t('bankTransfer') || 'تحويل بنكي'
            };
            return methods[method] || method;
        },
        getPaymentMethodIcon(method) {
            if (!method) return 'cash-stack';
            const icons = {
                'Cash': 'cash-stack',
                'Card': 'credit-card',
                'Credit': 'clock-history',
                'BankTransfer': 'bank'
            };
            return icons[method] || 'cash-stack';
        },
        getOrderTypeText(type) {
            if (!type) return '-';
            const types = {
                'DineIn': this.$t('dineIn') || 'داخلي',
                'Takeaway': this.$t('takeaway') || 'طلب خارجي',
                'Delivery': this.$t('delivery') || 'توصيل'
            };
            return types[type] || type;
        },
        isPublicMenuOrder(order) {
            const source = order?.orderSource ?? order?.OrderSource;
            return String(source || "").toLowerCase() === "publicmenu";
        },
        getOrderSourceText(source) {
            if (String(source || "").toLowerCase() === "publicmenu") {
                return this.$t("orderSourcePublicMenu") || "المنيو الإلكتروني";
            }
            return this.$t("orderSourcePos") || "كاشير مباشر";
        },
        getOrderTypeIcon(type) {
            if (!type) return 'house-door';
            const icons = {
                'DineIn': 'house-door',
                'Takeaway': 'bag',
                'Delivery': 'truck'
            };
            return icons[type] || 'house-door';
        },
        formatDate(dateTime) {
            return formatBusinessDateTime(dateTime);
        },
        formatPrice(price) {
            return formatMoney(price);
        },
        loadCommercialUserInfo() {
            HTTP.get("Admin/CommercialUserInfo")
                .then((response) => {
                    if (response.data && response.data.data) {
                        const d = response.data.data;
                        const format =
                            String(d.printInvoiceFormat || d.PrintInvoiceFormat || "Pos").toUpperCase() ===
                            "A4"
                                ? "A4"
                                : "Pos";
                        this.commercialUserInfo = {
                            storeName: d.storeName || d.StoreName || "LiteCashier",
                            logo: resolveAbsoluteAssetUrl(d.logo || d.Logo) || null,
                            printInvoiceFormat: format,
                            footerCreditText: d.footerCreditText || d.FooterCreditText || null,
                            footerCreditPhone: d.footerCreditPhone || d.FooterCreditPhone || null,
                        };
                        localStorage.setItem("printInvoiceFormat", format);
                    }
                })
                .catch((error) => {
                    console.error("Error loading commercial user info:", error);
                    this.commercialUserInfo = {
                        storeName: "LiteCashier",
                        logo: null,
                        printInvoiceFormat:
                            localStorage.getItem("printInvoiceFormat") === "A4" ? "A4" : "Pos",
                        footerCreditText: null,
                        footerCreditPhone: null,
                    };
                });
        },
        ensureOrderCodeForPrint() {
            const fromOrder = String(this.order?.orderCode || "").trim();
            if (fromOrder && fromOrder !== "---") {
                this.orderForSend.orderCode = fromOrder;
                return fromOrder;
            }
            const existing = String(this.orderForSend?.orderCode || "").trim();
            if (existing && existing !== "---") {
                return existing;
            }
            this.orderForSend.orderCode = Math.floor(Math.random() * 1000000000)
                .toString()
                .padStart(9, "0");
            return this.orderForSend.orderCode;
        },
        prepareOrderForPrint(order) {
            const items = (order?.customerOrderItem || []).filter((item) => !item.isDeleted);
            this.customerOrderItem = items;
            this.order = order || '';
            this.orderForSend = {
                ...this.orderForSend,
                orderCode: order?.orderCode || "",
                paymentMethod: order?.paymentMethod || "Cash",
            };
            return items;
        },
        async printReportInvoice() {
            if (this.printingInvoice) return;
            if (!this.customerOrderItem || this.customerOrderItem.length === 0) {
                this.$notify.error(this.$t("emptyCartMessage") || this.$t("emptyCart") || "لا توجد عناصر للطباعة", {
                    position: "top-right",
                    timeout: 2500,
                    maxToasts: 1,
                });
                return;
            }

            this.printingInvoice = true;
            try {
                this.ensureOrderCodeForPrint();
                await this.ensurePrintPrintersReady();
                await this.$nextTick();

                const htmlContent = await this.getReceiptHtmlContent();
                if (!htmlContent) {
                    this.notifyPrintError(this.$t("printError") || "تعذرت الطباعة");
                    return;
                }

                const printerId = this.resolvePrintPrinterId();
                const printer = this.findManagedPrinter(printerId);

                if (printerId && printer) {
                    try {
                        const apiOk = await this.printViaApi(printerId, htmlContent);
                        if (apiOk) {
                            this.notifyPrintSuccess();
                            return;
                        }
                    } catch (apiError) {
                        console.warn("[reports print] API failed, trying print server:", apiError);
                    }

                    const directOk = await this.printViaPrintServer(htmlContent, printer);
                    if (directOk) {
                        this.notifyPrintSuccess();
                        return;
                    }
                }

                await this.browserPrintReceipt(htmlContent);
                this.notifyPrintSuccess();
            } catch (error) {
                console.error("printReportInvoice error:", error);
                this.notifyPrintError(error.message);
            } finally {
                this.printingInvoice = false;
            }
        },
        async printOrderFromRow(order) {
            const items = this.prepareOrderForPrint(order);
            if (!items.length) {
                this.$notify.error(this.$t("emptyCartMessage") || this.$t("emptyCart") || "لا توجد عناصر للطباعة", {
                    position: "top-right",
                    timeout: 2500,
                    maxToasts: 1,
                });
                return;
            }
            this.$bvModal.show("modal-itemList");
            await this.$nextTick();
            await this.printReportInvoice();
        },

        showItemsModel(items, order) {
            this.customerOrderItem = (items || []).filter((item) => !item.isDeleted);
            this.order = order;
            this.orderForSend = {
                ...this.orderForSend,
                orderCode: order?.orderCode || "",
                paymentMethod: order?.paymentMethod || "Cash",
            };
            this.$bvModal.show("modal-itemList");
        },

        getItemInfo(item) {
            this.editForm = item;
            this.$bvModal.show("modal-editItem");
        },



        closeModel(id) {
            this.$bvModal.hide(id);
        },


        GetAllOrders() {
            this.show = true;
            const requestSeq = ++this.ordersRequestSeq;
            const params = new URLSearchParams();
            const apiPage = Math.max(0, (Number(this.pageNumber) || 1) - 1);
            params.append('pageNumber', apiPage.toString());
            params.append('pageSize', this.pageSize.toString());
            if ((this.search.info || '').trim()) params.append('info', this.search.info.trim());
            if (this.search.startDate) params.append('startDate', this.search.startDate);
            if (this.search.endDate) params.append('endDate', this.search.endDate);
            if (this.search.paymentMethod) params.append('paymentMethod', this.search.paymentMethod);
            if (this.search.orderSource) params.append('orderSource', this.search.orderSource);
            this.appendBrandIdParam(params, this.search.brandId);
            HTTP.get(`Admin/GetOrders?${params.toString()}`)
                .then((response) => {
                    if (requestSeq !== this.ordersRequestSeq) return;
                    const payload = response.data?.data || {};
                    this.Orders = payload.items || [];
                    this.totalOrders = Number(payload.totalItems) || 0;
                    // Keep UI page in sync if API clamped an out-of-range page after filtering.
                    if (payload.pageIndex != null) {
                        const uiPage = Number(payload.pageIndex) + 1;
                        if (uiPage > 0 && uiPage !== this.pageNumber) {
                            this.skipOrdersPageWatch = true;
                            this.pageNumber = uiPage;
                        }
                    }
                    const summary = payload.summary;
                    this.ordersSummary = {
                        totalOrders: summary?.totalOrders ?? this.totalOrders,
                        totalSubTotal: summary?.totalSubTotal ?? 0,
                        totalDiscount: summary?.totalDiscount ?? 0,
                        totalSales: summary?.totalSales ?? 0,
                        totalItemsSold: summary?.totalItemsSold ?? 0,
                        averageOrderValue: summary?.averageOrderValue ?? 0,
                    };
                    this.show = false;
                })
                .catch(() => {
                    if (requestSeq !== this.ordersRequestSeq) return;
                    this.show = false;
                });
        },

        editOrder(order) {
            this.editOrderData = order;
            this.editOrderForm = {
                paymentMethod: order.paymentMethod || 'Cash',
                discountType: order.discountType || null,
                discountValue: order.discountValue ?? null,
                items: order.customerOrderItem ? order.customerOrderItem.filter((item) => !item.isDeleted).map(item => ({
                    id: item.item?.id || item.itemId,
                    name: item.item?.name || '',
                    code: item.item?.code || '',
                    price: item.sellingPrice,
                    quantity: item.quantity,
                    itemId: item.itemId,
                })) : [],
            };
            this.$bvModal.show('modal-edit-order');
        },
        closeEditOrderModal() {
            this.editOrderData = null;
            this.editOrderForm = { paymentMethod: 'Cash', discountType: null, discountValue: null, items: [] };
            this.$bvModal.hide('modal-edit-order');
        },
        increaseEditItemQuantity(index) {
            if (this.editOrderForm.items[index]) this.editOrderForm.items[index].quantity++;
        },
        decreaseEditItemQuantity(index) {
            if (this.editOrderForm.items[index] && this.editOrderForm.items[index].quantity > 1) {
                this.editOrderForm.items[index].quantity--;
            }
        },
        removeEditItem(index) {
            this.editOrderForm.items.splice(index, 1);
        },
        showAddItemModal() {
            this.itemSearchQuery = '';
            this.availableItems = [];
            this.$bvModal.show('modal-add-item');
        },
        searchItems() {
            clearTimeout(this.itemSearchTimer);
            this.itemSearchTimer = setTimeout(() => {
                if (this.itemSearchQuery && this.itemSearchQuery.length >= 2) {
                    HTTP.get(`Admin/GetItems?pageNumber=0&pageSize=20&info=${encodeURIComponent(this.itemSearchQuery)}`)
                        .then((response) => { this.availableItems = response.data.data.items || []; })
                        .catch(() => { this.availableItems = []; });
                } else {
                    this.availableItems = [];
                }
            }, 300);
        },
        addItemToEditOrder(item) {
            const existingItem = this.editOrderForm.items.find(i => i.id === item.id);
            if (existingItem) {
                existingItem.quantity++;
            } else {
                let price;
                if (this.editOrderData?.isWholesale) {
                    const wholesale = Number(item.wholesalePrice) || 0;
                    price = wholesale > 0 ? wholesale : item.sellingPrice;
                } else {
                    price = item.disCountPrice > 0 && item.disCountPrice < item.sellingPrice ? item.disCountPrice : item.sellingPrice;
                }
                this.editOrderForm.items.push({ id: item.id, name: item.name, code: item.code, price, quantity: 1, itemId: item.id });
            }
            this.$bvModal.hide('modal-add-item');
        },
        async updateOrder() {
            if (!this.editOrderData || this.editOrderForm.items.length === 0) {
                this.$notify.error(this.$i18n.t('emptyCartMessage') || 'السلة فارغة', { position: 'top-right', timeout: 3000 });
                return;
            }
            this.loadingUpdateOrder = true;
            try {
                const request = {
                    paymentMethod: this.editOrderForm.paymentMethod,
                    isWholesale: !!this.editOrderData.isWholesale,
                    discountType: this.editOrderDiscountAmount > 0 ? this.editOrderForm.discountType : null,
                    discountValue: this.editOrderDiscountAmount > 0 ? (Number(this.editOrderForm.discountValue) || 0) : null,
                    discountAmount: this.editOrderDiscountAmount > 0 ? this.editOrderDiscountAmount : 0,
                    discountPercent: this.editOrderForm.discountType === 'percentage' ? (Number(this.editOrderForm.discountValue) || 0) : 0,
                    orderSubTotal: this.editOrderTotal,
                    orderTotalAfterDiscount: this.editOrderFinalTotal,
                    customerOrderItem: mergeCartLinesForOrderPayload(this.editOrderForm.items.map(item => ({
                        id: item.itemId || item.id,
                        quantity: item.quantity,
                    }))),
                };
                const response = await HTTP.put(`Admin/UpdateOrder/${this.editOrderData.id}`, request);
                if (response.data && !response.data.errorStatus) {
                    this.$notify.success(response.data.message || this.$i18n.t('orderUpdatedSuccessfully') || 'تم التحديث', { position: 'top-right', timeout: 3000 });
                    this.closeEditOrderModal();
                    this.GetAllOrders();
                } else {
                    this.$notify.error(response.data?.message || this.$i18n.t('error'), { position: 'top-right', timeout: 3000 });
                }
            } catch (error) {
                this.$notify.error(error.response?.data?.message || this.$i18n.t('error'), { position: 'top-right', timeout: 3000 });
            } finally {
                this.loadingUpdateOrder = false;
            }
        },
        async exportCurrentReportExcel() {
            this.exportingExcel = true;
            try {
                if (this.activeTab === 'orders') {
                    const params = new URLSearchParams();
                    if (this.search.info) params.append('info', this.search.info);
                    if (this.search.startDate) params.append('startDate', this.search.startDate);
                    if (this.search.endDate) params.append('endDate', this.search.endDate);
                    if (this.search.paymentMethod) params.append('paymentMethod', this.search.paymentMethod);
                    if (this.search.orderSource) params.append('orderSource', this.search.orderSource);
                    this.appendBrandIdParam(params, this.search.brandId);
                    const response = await HTTP.get(`Admin/ExportOrders?${params.toString()}`, { responseType: 'blob' });
                    const blob = new Blob([response.data], { type: 'text/csv;charset=utf-8;' });
                    const link = document.createElement('a');
                    link.href = URL.createObjectURL(blob);
                    link.download = `orders_${new Date().toISOString().split('T')[0]}.csv`;
                    link.click();
                    URL.revokeObjectURL(link.href);
                }
            } catch (e) {
                this.$notify.error(this.$t('exportError') || 'خطأ بالتصدير', { position: 'top-right', timeout: 3000 });
            } finally {
                this.exportingExcel = false;
            }
        },

        // Advanced Reports Methods
        loadAdvancedReport() {
            if (this.activeTab === 'profit') {
                this.loadProfitReport();
            } else if (this.activeTab === 'financialOps') {
                this.loadFinancialOperationsReport();
            } else if (this.activeTab === 'creditSettlements') {
                this.loadCreditSettlementsReport();
            } else if (this.activeTab === 'topItems') {
                this.loadTopSellingItems();
            } else if (this.activeTab === 'productSales') {
                this.loadProductSalesReport();
            } else if (this.activeTab === 'byCategory') {
                this.loadSalesByCategory();
            } else if (this.activeTab === 'byEmployee') {
                this.loadSalesByEmployee();
            } else if (this.activeTab === 'byWarehouse') {
                this.loadSalesByWarehouse();
            }
        },

        loadCreditSettlementsReport() {
            this.show = true;
            const params = new URLSearchParams();
            if (this.reportFilters.startDate) params.append("startDate", this.reportFilters.startDate);
            if (this.reportFilters.endDate) params.append("endDate", this.reportFilters.endDate);

            HTTP.get(`Admin/GetCreditSettlementsReport?${params.toString()}`)
                .then((response) => {
                    const data = response.data?.data ?? response.data?.Data ?? null;
                    this.creditSettlementsReport = {
                        count: data?.count ?? data?.Count ?? 0,
                        totalAmount: data?.totalAmount ?? data?.TotalAmount ?? 0,
                        breakdownByMethod: data?.breakdownByMethod ?? data?.BreakdownByMethod ?? [],
                        items: data?.items ?? data?.Items ?? [],
                        period: data?.period ?? data?.Period ?? {},
                    };
                })
                .catch((e) => {
                    console.error("Error loading credit settlements report:", e);
                    this.creditSettlementsReport = {
                        count: 0,
                        totalAmount: 0,
                        breakdownByMethod: [],
                        items: [],
                        period: {},
                    };
                    this.$notify.error(
                        this.$t("loadReportError") || "فشل تحميل التقرير",
                        { position: "top-right", timeout: 3000 }
                    );
                })
                .finally(() => {
                    this.show = false;
                });
        },

        openFinancialOpsTab() {
            this.ensureExpenseCategoriesForReport().then(() => {
                this.loadFinancialOperationsReport();
            });
        },

        isFinancialOpsCategorySelected(name) {
            return (this.financialOpsSelectedCategories || []).includes(name);
        },

        clearFinancialOpsCategories() {
            this.financialOpsSelectedCategories = [];
            this.loadFinancialOperationsReport();
        },

        async ensureExpenseCategoriesForReport() {
            if (this.expenseCategoriesForReport.length > 0) return;
            try {
                const response = await HTTP.get("ExpenseCategories");
                const raw = response.data?.data ?? response.data?.Data ?? [];
                this.expenseCategoriesForReport = (Array.isArray(raw) ? raw : [])
                    .map((c) => ({
                        id: c.id ?? c.Id,
                        name: (c.name ?? c.Name ?? "").trim(),
                    }))
                    .filter((c) => c.name);
            } catch (e) {
                console.error("Error loading expense categories:", e);
                this.expenseCategoriesForReport = [];
            }
        },

        loadFinancialOperationsReport() {
            this.show = true;
            const params = new URLSearchParams();
            if (this.reportFilters.startDate) params.append("startDate", this.reportFilters.startDate);
            if (this.reportFilters.endDate) params.append("endDate", this.reportFilters.endDate);
            this.appendBrandIdParam(params, this.reportBrandId);
            if ((this.financialOpsSelectedCategories || []).length) {
                params.append("categories", this.financialOpsSelectedCategories.join(","));
            }

            HTTP.get(`Admin/GetFinancialOperationsReport?${params.toString()}`)
                .then((response) => {
                    const data = response.data?.data || response.data?.Data || {};
                    this.financialOpsReport = {
                        totalSales: data.totalSales ?? data.TotalSales ?? 0,
                        totalCost: data.totalCost ?? data.TotalCost ?? 0,
                        totalProfit: data.totalProfit ?? data.TotalProfit ?? 0,
                        totalExpenses: data.totalExpenses ?? data.TotalExpenses ?? 0,
                        actualCash: data.actualCash ?? data.ActualCash ?? 0,
                        selectedCategoriesTotal:
                            data.selectedCategoriesTotal ?? data.SelectedCategoriesTotal ?? 0,
                        netProfit: data.netProfit ?? data.NetProfit ?? 0,
                        selectedCategories:
                            data.selectedCategories || data.SelectedCategories || [],
                        selectedCategoryBreakdown: (
                            data.selectedCategoryBreakdown ||
                            data.SelectedCategoryBreakdown ||
                            []
                        ).map((row) => ({
                            category: row.category ?? row.Category ?? "",
                            totalAmount: row.totalAmount ?? row.TotalAmount ?? 0,
                            count: row.count ?? row.Count ?? 0,
                            isSelected: row.isSelected ?? row.IsSelected ?? true,
                        })),
                        expensesByCategory: (
                            data.expensesByCategory ||
                            data.ExpensesByCategory ||
                            []
                        ).map((row) => ({
                            category: row.category ?? row.Category ?? "",
                            totalAmount: row.totalAmount ?? row.TotalAmount ?? 0,
                            count: row.count ?? row.Count ?? 0,
                            isSelected: !!(row.isSelected ?? row.IsSelected),
                        })),
                        period: data.period || data.Period || {},
                    };
                    this.mergeExpenseCategoriesFromReport(this.financialOpsReport.expensesByCategory);
                    this.show = false;
                })
                .catch((error) => {
                    this.show = false;
                    console.error("Error loading financial operations report:", error);
                });
        },

        mergeExpenseCategoriesFromReport(rows) {
            const known = new Set(
                (this.expenseCategoriesForReport || []).map((c) => (c.name || "").trim())
            );
            (rows || []).forEach((row) => {
                const name = (row.category || "").trim();
                if (!name || name === "-" || known.has(name)) return;
                known.add(name);
                this.expenseCategoriesForReport.push({ id: `exp-${name}`, name });
            });
        },

        loadProductSalesReport() {
            this.show = true;
