<script>
import AppHeader from "@/components/Layout/AppHeader.vue";
import { HTTP } from "@/http/api.js";
import { resolveAbsoluteAssetUrl } from "@/utils/apiBase.js";
import { applyCommercialBranding, clampWatermarkOpacity, normalizePosLayout } from "@/utils/posBranding.js";
import { BUILTIN_DEFAULT_PRODUCT_IMAGE } from "@/utils/productImage.js";
import { resolveCommercialUserId } from "@/utils/publicMenu.js";

export default {
  name: "SettingsView",
  components: { AppHeader },
  data() {
    return {
      clearCatalogPassword: "",
      clearCatalogLoading: false,
      clearCatalogResult: null,
      backupLoading: false,
      printInvoiceFormat: "Pos",
      savedPrintInvoiceFormat: "Pos",
      printSettingsLoading: false,
      printSettingsSaving: false,
      publicMenuMinOrderAmount: 0,
      savedPublicMenuMinOrderAmount: 0,
      publicMenuSettingsLoading: false,
      publicMenuSettingsSaving: false,
      savingLogo: false,
      currentLogo: null,
      logoFile: null,
      logoPreview: null,
      brandingLoading: false,
      brandingSaving: false,
      posLayout: "Classic",
      savedPosLayout: "Classic",
      cartWatermarkOpacity: 18,
      savedCartWatermarkOpacity: 18,
      savedWatermarkLogo: null,
      savedDefaultProductImage: null,
      watermarkFile: null,
      watermarkPreview: null,
      defaultProductFile: null,
      defaultProductPreview: null,
      clearWatermarkPending: false,
      clearDefaultProductPending: false,
      menuAds: [],
      menuAdsLoading: false,
      menuAdsUploading: false,
      menuAdsDeletingId: null,
      menuAdTitle: "",
    };
  },
  computed: {
    commercialUserId() {
      return resolveCommercialUserId();
    },
    printFormatDirty() {
      return this.printInvoiceFormat !== this.savedPrintInvoiceFormat;
    },
    publicMenuMinDirty() {
      return this.normalizeMinOrderAmount(this.publicMenuMinOrderAmount)
        !== this.savedPublicMenuMinOrderAmount;
    },
    watermarkPreviewSrc() {
      if (this.clearWatermarkPending) return null;
      return this.watermarkPreview || this.savedWatermarkLogo;
    },
    defaultProductPreviewSrc() {
      if (this.clearDefaultProductPending) return BUILTIN_DEFAULT_PRODUCT_IMAGE;
      return this.defaultProductPreview || this.savedDefaultProductImage || BUILTIN_DEFAULT_PRODUCT_IMAGE;
    },
    hasCustomDefaultProduct() {
      return !!(this.defaultProductFile || (!this.clearDefaultProductPending && this.savedDefaultProductImage));
    },
    brandingDirty() {
      return (
        !!this.watermarkFile ||
        !!this.defaultProductFile ||
        this.clearWatermarkPending ||
        this.clearDefaultProductPending ||
        clampWatermarkOpacity(this.cartWatermarkOpacity) !== this.savedCartWatermarkOpacity ||
        normalizePosLayout(this.posLayout) !== normalizePosLayout(this.savedPosLayout)
      );
    },
  },
  mounted() {
    this.loadPrintSettings();
    this.loadPosBranding();
    this.loadMenuAds();
    this.$nextTick(() => {
      if (this.$route.hash === "#menu-ads") {
        document.getElementById("menu-ads")?.scrollIntoView({ behavior: "smooth", block: "start" });
      }
    });
  },
  beforeDestroy() {
    this.revokeBrandingPreviews();
  },
  methods: {
    async loadPrintSettings() {
      this.printSettingsLoading = true;
      this.publicMenuSettingsLoading = true;
      try {
        const response = await HTTP.get("Admin/CommercialUserInfo");
        const d = response?.data?.data;
        if (d) {
          const format =
            String(d.printInvoiceFormat || d.PrintInvoiceFormat || "Pos").toUpperCase() ===
            "A4"
              ? "A4"
              : "Pos";
          this.printInvoiceFormat = format;
          this.savedPrintInvoiceFormat = format;
          localStorage.setItem("printInvoiceFormat", format);
          this.currentLogo = resolveAbsoluteAssetUrl(d.logo || d.Logo) || null;
          const minOrder = this.normalizeMinOrderAmount(
            d.publicMenuMinOrderAmount != null
              ? d.publicMenuMinOrderAmount
              : d.PublicMenuMinOrderAmount
          );
          this.publicMenuMinOrderAmount = minOrder;
          this.savedPublicMenuMinOrderAmount = minOrder;
        }
      } catch (error) {
        console.error("Error loading print settings:", error);
        const cached = localStorage.getItem("printInvoiceFormat") === "A4" ? "A4" : "Pos";
        this.printInvoiceFormat = cached;
        this.savedPrintInvoiceFormat = cached;
      } finally {
        this.printSettingsLoading = false;
        this.publicMenuSettingsLoading = false;
      }
    },
    async savePrintSettings() {
      if (this.printSettingsSaving || !this.printFormatDirty) return;
      this.printSettingsSaving = true;
      try {
        const response = await HTTP.post("Admin/UpdatePrintSettings", {
          printInvoiceFormat: this.printInvoiceFormat,
        });
        if (response?.data?.errorStatus) {
          throw new Error(response.data.message || "saveFailed");
        }
        const d = response?.data?.data;
        const format =
          String(d?.printInvoiceFormat || d?.PrintInvoiceFormat || this.printInvoiceFormat)
            .toUpperCase() === "A4"
            ? "A4"
            : "Pos";
        this.printInvoiceFormat = format;
        this.savedPrintInvoiceFormat = format;
        localStorage.setItem("printInvoiceFormat", format);
        this.$notify.success(this.$t("settingsPrintSaveSuccess"), {
          position: "top-right",
          timeout: 3000,
          maxToasts: 1,
        });
      } catch (error) {
        const msg = error?.response?.data?.message || error?.message;
        this.$notify.error(
          msg && this.$te(msg) ? this.$t(msg) : this.$t("settingsPrintSaveFailed"),
          { position: "top-right", timeout: 4000, maxToasts: 1 }
        );
      } finally {
        this.printSettingsSaving = false;
      }
    },
    normalizeMinOrderAmount(value) {
      const n = Number(value);
      if (!Number.isFinite(n) || n < 0) return 0;
      return Math.round(n);
    },
    async savePublicMenuSettings() {
      if (this.publicMenuSettingsSaving || !this.publicMenuMinDirty) return;
      this.publicMenuSettingsSaving = true;
      try {
        const amount = this.normalizeMinOrderAmount(this.publicMenuMinOrderAmount);
        const response = await HTTP.post("Admin/UpdatePublicMenuSettings", {
          publicMenuMinOrderAmount: amount,
        });
        if (response?.data?.errorStatus) {
          throw new Error(response.data.message || "saveFailed");
        }
        this.publicMenuMinOrderAmount = amount;
        this.savedPublicMenuMinOrderAmount = amount;
        this.$notify.success(this.$t("settingsPublicMenuSaveSuccess"), {
          position: "top-right",
          timeout: 3000,
          maxToasts: 1,
        });
      } catch (error) {
        const msg = error?.response?.data?.message || error?.message;
        this.$notify.error(
          msg && this.$te(msg) ? this.$t(msg) : this.$t("settingsPublicMenuSaveFailed"),
          { position: "top-right", timeout: 4000, maxToasts: 1 }
        );
      } finally {
        this.publicMenuSettingsSaving = false;
      }
    },
    handleLogoChange(event) {
      const file = event?.target?.files?.[0];
      if (this.$refs.logoInput) this.$refs.logoInput.value = "";
      if (!file) return;
      this.logoFile = file;
      const reader = new FileReader();
      reader.onload = (e) => {
        this.logoPreview = e.target.result;
      };
      reader.readAsDataURL(file);
    },
    async removeLogo() {
      if (this.savingLogo) return;
      const hadSavedLogo = !!this.currentLogo;
      const previousLogo = this.currentLogo;
      this.logoFile = null;
      this.logoPreview = null;
      this.currentLogo = null;
      if (this.$refs.logoInput) this.$refs.logoInput.value = "";
      if (!hadSavedLogo) return;

      this.savingLogo = true;
      try {
        const formData = new FormData();
        formData.append("ClearLogo", "true");
        const res = await HTTP.post("Admin/UpdateMyProfile", formData, {
          headers: { "Content-Type": "multipart/form-data" },
        });
        if (res?.data?.errorStatus) {
          throw new Error(res.data.message || "saveFailed");
        }
        this.$notify.success(this.$t("logoRemoveSuccess") || "تم إزالة الشعار", {
          position: "top-right",
          timeout: 2500,
          maxToasts: 1,
        });
      } catch (err) {
        this.currentLogo = previousLogo;
        const msg = err?.response?.data?.message || err?.message;
        this.$notify.error(
          msg || this.$t("logoRemoveFailed") || "تعذر إزالة الشعار",
          { position: "top-right", timeout: 4000, maxToasts: 1 }
        );
      } finally {
        this.savingLogo = false;
      }
    },
    async saveLogo() {
      if (!this.logoFile || this.savingLogo) return;
      this.savingLogo = true;
      try {
        const formData = new FormData();
        formData.append("logo", this.logoFile);
        const res = await HTTP.post("Admin/UpdateMyProfile", formData, {
          headers: { "Content-Type": "multipart/form-data" },
        });
        if (res?.data?.errorStatus) {
          throw new Error(res.data.message || "saveFailed");
        }
        const d = res?.data?.data;
        if (d?.logo || d?.Logo) {
          this.currentLogo = resolveAbsoluteAssetUrl(d.logo || d.Logo);
        }
        this.logoFile = null;
        this.logoPreview = null;
        this.$notify.success(this.$t("logoSaveSuccess") || "تم حفظ الشعار بنجاح", {
          position: "top-right",
          timeout: 3000,
          maxToasts: 1,
        });
      } catch (err) {
        const msg = err?.response?.data?.message || err?.message;
        this.$notify.error(
          msg || this.$t("saveFailed") || "حدث خطأ أثناء رفع الشعار",
          { position: "top-right", timeout: 4000, maxToasts: 1 }
        );
      } finally {
        this.savingLogo = false;
      }
    },
    applyBrandingPayload(d) {
      const branding = applyCommercialBranding(d);
      this.posLayout = branding.posLayout;
      this.savedPosLayout = branding.posLayout;
      this.savedWatermarkLogo = branding.cartWatermarkLogo;
      this.savedDefaultProductImage = branding.defaultProductImage;
      this.cartWatermarkOpacity = branding.cartWatermarkOpacity;
      this.savedCartWatermarkOpacity = branding.cartWatermarkOpacity;
      this.clearWatermarkPending = false;
      this.clearDefaultProductPending = false;
      this.revokeBrandingPreviews();
      this.watermarkFile = null;
      this.watermarkPreview = null;
      this.defaultProductFile = null;
      this.defaultProductPreview = null;
    },
    revokeBrandingPreviews() {
      if (this.watermarkPreview) URL.revokeObjectURL(this.watermarkPreview);
      if (this.defaultProductPreview) URL.revokeObjectURL(this.defaultProductPreview);
    },
    async loadPosBranding() {
      this.brandingLoading = true;
      try {
        const response = await HTTP.get("Admin/CommercialUserInfo");
        this.applyBrandingPayload(response?.data?.data);
      } catch (error) {
        console.error("Error loading POS branding:", error);
      } finally {
        this.brandingLoading = false;
      }
    },
    onWatermarkFileChange(event) {
      const file = event?.target?.files?.[0];
      if (this.$refs.watermarkInput) this.$refs.watermarkInput.value = "";
      if (!file) return;
      if (this.watermarkPreview) URL.revokeObjectURL(this.watermarkPreview);
      this.watermarkFile = file;
      this.watermarkPreview = URL.createObjectURL(file);
      this.clearWatermarkPending = false;
    },
    clearWatermark() {
      if (this.watermarkPreview) URL.revokeObjectURL(this.watermarkPreview);
      this.watermarkFile = null;
      this.watermarkPreview = null;
      this.clearWatermarkPending = !!this.savedWatermarkLogo;
    },
    onDefaultProductFileChange(event) {
      const file = event?.target?.files?.[0];
      if (this.$refs.defaultProductInput) this.$refs.defaultProductInput.value = "";
      if (!file) return;
      if (this.defaultProductPreview) URL.revokeObjectURL(this.defaultProductPreview);
      this.defaultProductFile = file;
      this.defaultProductPreview = URL.createObjectURL(file);
      this.clearDefaultProductPending = false;
    },
    clearDefaultProduct() {
      if (this.defaultProductPreview) URL.revokeObjectURL(this.defaultProductPreview);
      this.defaultProductFile = null;
      this.defaultProductPreview = null;
      this.clearDefaultProductPending = !!this.savedDefaultProductImage;
    },
    async savePosBranding() {
      if (this.brandingSaving || !this.brandingDirty) return;
      this.brandingSaving = true;
      try {
        const formData = new FormData();
        formData.append("CartWatermarkOpacity", String(clampWatermarkOpacity(this.cartWatermarkOpacity)));
        formData.append("PosLayout", normalizePosLayout(this.posLayout));
        if (this.watermarkFile) formData.append("CartWatermarkLogo", this.watermarkFile);
        if (this.clearWatermarkPending) formData.append("ClearCartWatermark", "true");
        if (this.defaultProductFile) formData.append("DefaultProductImage", this.defaultProductFile);
        if (this.clearDefaultProductPending) formData.append("ClearDefaultProductImage", "true");

        const response = await HTTP.post("Admin/UpdatePosBranding", formData);
        if (response?.data?.errorStatus) {
          throw new Error(response.data.message || "saveFailed");
        }
        this.applyBrandingPayload(response?.data?.data);
        this.$notify.success(this.$t("settingsPosBrandingSaveSuccess"), {
          position: "top-right",
          timeout: 3000,
          maxToasts: 1,
        });
      } catch (error) {
        const msg = error?.response?.data?.message || error?.message;
        this.$notify.error(
          msg && this.$te(msg) ? this.$t(msg) : this.$t("settingsPosBrandingSaveFailed"),
          { position: "top-right", timeout: 4000, maxToasts: 1 }
        );
      } finally {
        this.brandingSaving = false;
      }
    },
    mapMenuAd(ad) {
      return {
        id: ad.id ?? ad.Id,
        image: ad.image ?? ad.Image,
        title: (ad.title ?? ad.Title) || "",
      };
    },
    async loadMenuAds() {
      if (!this.commercialUserId) return;
      this.menuAdsLoading = true;
      try {
        const response = await HTTP.get(`PublicMenu/${this.commercialUserId}/ads`);
        if (response?.data?.errorStatus) throw new Error(response.data.message);
        this.menuAds = (response?.data?.data || []).map(this.mapMenuAd);
      } catch {
        this.menuAds = [];
      } finally {
        this.menuAdsLoading = false;
      }
    },
    async onMenuAdFileChange(event) {
      const file = event?.target?.files?.[0];
      if (this.$refs.menuAdInput) this.$refs.menuAdInput.value = "";
      if (!file || !this.commercialUserId || this.menuAdsUploading) return;
      this.menuAdsUploading = true;
      try {
        const formData = new FormData();
        formData.append("image", file);
        if (this.menuAdTitle) formData.append("title", this.menuAdTitle);
        const response = await HTTP.post(`PublicMenu/${this.commercialUserId}/ads`, formData);
        if (response?.data?.errorStatus) throw new Error(response.data.message);
        const created = response?.data?.data;
        if (created) this.menuAds.push(this.mapMenuAd(created));
        this.menuAdTitle = "";
        this.$notify.success(this.$t("menuAdsUploadSuccess"), {
          position: "top-right",
          timeout: 3000,
          maxToasts: 1,
        });
      } catch (error) {
        const msg = error?.response?.data?.message || error?.message;
        this.$notify.error(
          msg && this.$te(msg) ? this.$t(msg) : this.$t("menuAdsUploadFailed"),
          { position: "top-right", timeout: 4000, maxToasts: 1 }
        );
      } finally {
        this.menuAdsUploading = false;
      }
    },
    async deleteMenuAd(ad) {
      if (!ad?.id || !this.commercialUserId) return;
      const ok = await this.$confirm({
        title: this.$t("menuAdsRemove"),
        message: this.$t("menuAdsRemoveConfirm"),
        variant: "danger",
        icon: "trash",
        confirmText: this.$t("menuAdsRemove"),
      });
      if (!ok) return;
      this.menuAdsDeletingId = ad.id;
      try {
        const response = await HTTP.delete(`PublicMenu/${this.commercialUserId}/ads/${ad.id}`);
        if (response?.data?.errorStatus) throw new Error(response.data.message);
        this.menuAds = this.menuAds.filter((row) => row.id !== ad.id);
        this.$notify.success(this.$t("menuAdsRemoveSuccess"), {
          position: "top-right",
          timeout: 3000,
          maxToasts: 1,
        });
      } catch {
        this.$notify.error(this.$t("menuAdsRemoveFailed"), {
          position: "top-right",
          timeout: 4000,
          maxToasts: 1,
        });
      } finally {
        this.menuAdsDeletingId = null;
      }
    },
    async downloadDatabaseBackup() {
      if (this.backupLoading) return;
      this.backupLoading = true;
      try {
        const response = await HTTP.get("Admin/DownloadDatabaseBackup", {
          responseType: "blob",
          timeout: 300000,
        });

        const contentType = response.headers["content-type"] || "";
        if (contentType.includes("application/json")) {
          const text = await response.data.text();
          const payload = JSON.parse(text);
          const msg = payload?.message;
          throw new Error(msg || "backupFailed");
        }

        const disposition = response.headers["content-disposition"] || "";
        const matchedName = /filename\*?=(?:UTF-8'')?["']?([^"';]+)/i.exec(disposition);
        const fallbackName = `litecashier-backup-${new Date().toISOString().slice(0, 19).replace(/[:T]/g, "-")}.sql`;
        const fileName = decodeURIComponent(
          (matchedName?.[1] || fallbackName).replace(/"/g, "")
        );

        const blob = new Blob([response.data], { type: "application/sql" });
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = fileName;
        document.body.appendChild(link);
        link.click();
        link.remove();
        URL.revokeObjectURL(url);

        this.$notify.success(this.$t("settingsBackupSuccess"), {
          position: "top-right",
          timeout: 4000,
          maxToasts: 1,
        });
      } catch (error) {
        let msg = error?.message;
        if (error?.response?.data instanceof Blob) {
          try {
            const text = await error.response.data.text();
            const payload = JSON.parse(text);
            msg = payload?.message || msg;
          } catch (_) {
            /* ignore */
          }
        } else {
          msg = error?.response?.data?.message || msg;
        }
        const text =
          msg && this.$te(msg) ? this.$t(msg) : this.$t("settingsBackupFailed");
        this.$notify.error(text, {
          position: "top-right",
          timeout: 4500,
          maxToasts: 1,
        });
      } finally {
        this.backupLoading = false;
      }
    },
    closeClearCatalogModal() {
      this.$bvModal.hide("modal-clearCatalog");
      this.clearCatalogPassword = "";
      this.clearCatalogResult = null;
      this.clearCatalogLoading = false;
    },
    async executeClearCatalog() {
      if (!this.clearCatalogPassword || this.clearCatalogLoading) return;

      this.clearCatalogLoading = true;
      this.clearCatalogResult = null;

      try {
        const response = await HTTP.post("Admin/ClearCatalog", {
          password: this.clearCatalogPassword,
        });
        const payload = response?.data;
        this.clearCatalogResult = payload?.data || null;

        this.$notify.success(
          this.$te(payload?.message) ? this.$t(payload.message) : this.$t("catalogClearSuccess"),
          { position: "top-right", timeout: 4500, maxToasts: 1 }
        );
      } catch (error) {
        const msg = error?.response?.data?.message;
        const text =
          msg && this.$te(msg) ? this.$t(msg) : this.$t("catalogClearFailed");
        this.$notify.error(text, {
          position: "top-right",
          timeout: 4000,
          maxToasts: 1,
        });
      } finally {
        this.clearCatalogLoading = false;
      }
    },
  },
};
</script>

