            </div>

            <div class="users-form-actions">
              <button type="submit" class="users-form-submit-button" :disabled="show == true">
                <b-spinner small v-if="show == true" class="me-2"></b-spinner>
                <b-icon v-else icon="check-circle-fill" class="me-2"></b-icon>
                {{ $t("editItemButtonLabel") }}
              </button>
              <button type="button" class="users-form-cancel-button" @click="closeModel('modal-editItem')">
                <b-icon icon="x-circle-fill" class="me-2"></b-icon>
                {{ $t("closeButton") }}
              </button>
            </div>
          </form>
        </div>
      </b-modal>

      <!-- Delete Confirmation Modal -->
      <b-modal id="modal-delete" :title="$t('deleteConfirmationModalTitle')" hide-header hide-footer class="users-modal">
        <div class="modal-content-wrapper">
          <div class="delete-confirmation-content">
            <div class="delete-icon-wrapper">
              <b-icon icon="exclamation-triangle-fill" class="delete-warning-icon"></b-icon>
            </div>
            <h3 class="delete-confirmation-title">{{ $t("deleteConfirmationMessage") }}</h3>
            <p class="delete-confirmation-text">{{ $t("areYouSureDeleteUser") || 'هل أنت متأكد من حذف هذا المنتج؟' }}</p>
            <div class="delete-confirmation-actions">
              <button class="delete-confirm-button" @click="deleteItem('modal-delete')">
                <b-icon icon="check-circle-fill" class="me-2"></b-icon>
                {{ $t("deleteButtonLabel") }}
              </button>
              <button class="delete-cancel-button" @click="closeModel('modal-delete')">
                <b-icon icon="x-circle-fill" class="me-2"></b-icon>
                {{ $t("cancelButtonLabel") }}
              </button>
            </div>
          </div>
        </div>
      </b-modal>

      <!-- Manage item QR / barcode codes -->
      <b-modal
        id="modal-itemCodes"
        hide-header
        hide-footer
        class="users-modal"
        size="lg"
        @hidden="resetItemCodesModal"
      >
        <div class="modal-content-wrapper">
          <h2 class="modal-title">{{ $t("manageItemCodes") || "إدارة أكواد المنتج" }}</h2>
          <p class="item-codes-subtitle" v-if="codesModalItem">
            {{ codesModalItem.name }}
          </p>

          <div class="item-codes-primary" v-if="codesModalItem">
            <label class="users-form-label">{{ $t("primaryItemCode") || "الكود الأساسي" }}</label>
            <div class="item-codes-primary-row">
              <code class="item-codes-primary-value">{{ codesModalPrimary || "—" }}</code>
              <small class="item-codes-hint">{{ $t("primaryItemCodeHint") || "يُعدَّل من شاشة تعديل المنتج" }}</small>
            </div>
            <div class="item-codes-barcode" v-if="codesModalPrimary">
              <vue-barcode
                tag="svg"
                :value="String(codesModalPrimary)"
                :options="{ displayValue: true, width: 1.4, height: 48, margin: 4 }"
              />
            </div>
          </div>

          <div class="item-codes-add-row">
            <input
              v-model="newItemCode"
              type="text"
              class="users-form-input"
              :placeholder="$t('addItemCodePlaceholder') || 'أدخل كود / QR إضافي'"
              @keyup.enter="addItemCode"
            />
            <button
              type="button"
              class="users-form-submit-button item-codes-add-btn"
              :disabled="codesModalSaving || !String(newItemCode || '').trim()"
              @click="addItemCode"
            >
              <b-spinner small v-if="codesModalSaving"></b-spinner>
              <template v-else>
                <b-icon icon="plus-circle-fill" class="me-1"></b-icon>
                {{ $t("addItemCode") || "إضافة" }}
              </template>
            </button>
          </div>

          <div v-if="codesModalLoading" class="item-codes-loading">
            <b-spinner variant="primary"></b-spinner>
          </div>
          <div v-else-if="!codesModalList.length" class="item-codes-empty">
            {{ $t("itemCodesEmpty") || "لا توجد أكواد إضافية بعد" }}
          </div>
          <ul v-else class="item-codes-list">
            <li v-for="row in codesModalList" :key="row.id" class="item-codes-list-item">
              <div class="item-codes-list-main">
                <code>{{ row.code }}</code>
                <vue-barcode
                  tag="svg"
                  class="item-codes-list-barcode"
                  :value="String(row.code)"
                  :options="{ displayValue: false, width: 1.1, height: 32, margin: 0 }"
                />
              </div>
              <button
                type="button"
                class="action-btn action-btn--icon action-btn--delete"
                :disabled="codesModalDeletingId === row.id"
                :title="$t('deleteButtonLabel')"
                @click="deleteItemCode(row.id)"
              >
                <b-spinner small v-if="codesModalDeletingId === row.id"></b-spinner>
                <b-icon v-else icon="trash-fill" class="action-icon"></b-icon>
              </button>
            </li>
          </ul>

          <div class="users-form-actions">
            <button type="button" class="users-form-cancel-button" @click="closeModel('modal-itemCodes')">
              {{ $t("closeButton") || "إغلاق" }}
            </button>
          </div>
        </div>
      </b-modal>

      <!-- Print QR / barcode labels (label printer, not A4) -->
      <b-modal
        id="modal-printLabels"
        hide-header
        hide-footer
        class="users-modal"
        size="md"
        @hidden="resetPrintLabelsModal"
      >
        <div class="modal-content-wrapper" v-if="printLabelItem">
          <h2 class="modal-title">{{ $t("printCodeButtonLabel") || "طباعة الكود" }}</h2>
          <p class="users-form-hint">
            {{ $t("printQrLabelHint") || "مخصص لطابعات ملصقات HPRT (مثل N41) — ليس ورق A4. العرض الأدنى 50 مم." }}
          </p>

          <div class="users-form-group">
            <label class="users-form-label">{{ $t("itemNamePlaceholder") || "اسم المنتج" }}</label>
            <input class="users-form-input" type="text" :value="printLabelItem.name" readonly />
          </div>
          <div class="users-form-group">
            <label class="users-form-label">{{ $t("itemCodePlaceholder") || "الكود" }}</label>
            <input class="users-form-input" type="text" :value="printLabelItem.code" readonly />
          </div>

          <div class="users-form-group">
            <label class="users-form-label">{{ $t("printQrLabelSize") || "حجم الملصق" }}</label>
            <select v-model="printLabelSizeId" class="users-form-select">
              <option
                v-for="size in qrLabelSizes"
                :key="size.id"
                :value="size.id"
              >
                {{ formatLabelSizeOption(size) }}
              </option>
            </select>
            <small class="users-form-hint" style="display:block;margin-top:0.4rem;">
              {{ $t("printQrLabelDriverHint") || "في إعدادات طابعة HPRT اختر نفس الحجم، Sensor=Gap، والهوامش 0 بدون Fit to page." }}
            </small>
          </div>

          <div class="users-form-group">
            <label class="users-form-label">{{ $t("printQrLabelOrientation") || "اتجاه الطباعة" }}</label>
            <select v-model="printLabelOrientation" class="users-form-select">
              <option value="landscape">{{ $t("printQrLabelOrientationLandscape") || "بالعرض (أفقي)" }}</option>
              <option value="portrait">{{ $t("printQrLabelOrientationPortrait") || "بالطول (عمودي)" }}</option>
            </select>
            <small class="users-form-hint" style="display:block;margin-top:0.4rem;">
              {{ $t("printQrLabelOrientationHint") || "إذا طُبع الملصق بالطول فقط، اختر بالعرض. تأكد أيضاً أن اتجاه الطابعة في ويندوز/تعريف HPRT مطابق." }}
            </small>
          </div>

          <div class="users-form-group">
            <label class="users-form-label">{{ $t("printQrLabelCopies") || "عدد الملصقات" }}</label>
            <input
              v-model.number="printLabelCopies"
              type="number"
              min="1"
              max="200"
              class="users-form-input"
            />
          </div>

          <div class="users-form-actions">
            <button type="button" class="users-form-submit-button" @click="confirmPrintLabels">
              <b-icon icon="printer-fill" class="me-2"></b-icon>
              {{ $t("print") || "طباعة" }}
            </button>
            <button
              type="button"
              class="users-form-cancel-button"
              @click="closeModel('modal-printLabels')"
            >
              <b-icon icon="x-circle-fill" class="me-2"></b-icon>
              {{ $t("closeButtonLabel") || $t("close") || "إغلاق" }}
            </button>
          </div>
        </div>
      </b-modal>
    </div>
  </b-overlay>
</template>
<script>
import AppHeader from "@/components/Layout/AppHeader.vue";
import ClockVue from "@/components/ClockVue.vue";
import VueBarcode from "@chenfengyuan/vue-barcode";

import { HTTP } from "../http/api.js";
import { BUSINESS_TIME_ZONE } from "@/utils/formatBusinessDateTime.js";
import { formatMoney as formatMoneyLatn } from "@/utils/formatMoney.js";
import { computeWeightedAverageCost } from "@/utils/inventoryCost.js";
import {
  productImageSrc,
  isProductImageFallback,
  onProductImageError,
} from "@/utils/productImage.js";
import {
  QR_LABEL_SIZES,
  DEFAULT_QR_LABEL_SIZE_ID,
  DEFAULT_QR_LABEL_ORIENTATION,
  formatQrLabelSizeOption,
  printQrLabels,
} from "@/utils/qrLabelPrint.js";
export default {
  name: "ItemsView",
  components: {
    AppHeader,
    ClockVue,
    "vue-barcode": VueBarcode,
  },
  data() {
    return {
      selected: null,
      options: ["list", "of", "options"],
      show: false,
      Items: [],
      pageNumber: 1,
      totalItems: 0,
      pageSize: 12,
      search: {
        info: "",
        tag: "",
        brandId: "",
        stockStatus: "",
      },
      SearchItems: [],
      totalCardItems: 0,
      userInfo: {},
      editForm: {
        name: "",
        description: "",
        sellingPrice: 0,
        purchasingPrice: 0,
        disCountPrice: 0,
        wholesalePrice: 0,
        tags: "مواد اخرى",
        brandId: "",
        code: "",
        id: "",
        quantity: 0,
        lowStockAlertQuantity: "",
        expiryDate: "",
      },
      imagePreview: "",
      itemPhoto: null,
      itemImage: "",
      showUpload: false,
      addForm: {
        name: "",
        description: "",
        sellingPrice: 0,
        purchasingPrice: 0,
        disCountPrice : 0,
        wholesalePrice: 0,
        tags: "مواد اخرى",
        brandId: "",
        code: "",
        quantity: 0,
        lowStockAlertQuantity: "",
        expiryDate: "",
      },
      barCodeList: [],
      printLabelItem: null,
      printLabelCopies: 1,
      printLabelSizeId: DEFAULT_QR_LABEL_SIZE_ID,
      printLabelOrientation: DEFAULT_QR_LABEL_ORIENTATION,
      qrLabelSizes: QR_LABEL_SIZES,
      itemId: "",
      tags: [],
      brands: [],
      importFile: null,
      importFileName: "",
      importUploading: false,
      importResult: null,
      codesModalItem: null,
      codesModalPrimary: "",
      codesModalList: [],
      codesModalLoading: false,
      codesModalSaving: false,
      codesModalDeletingId: null,
      newItemCode: "",
      warehouses: [],
      warehouseStockRows: [],
      editWarehouseStockRows: [],
      editBaselineQuantity: 0,
      editBaselinePurchasingPrice: 0,
      stockEntries: [],
      stockEntriesLoading: false,
      stockEntrySaving: false,
      stockEntryEditingId: null,
      stockEntryEditingSnapshot: null,
      stockEntryForm: {
        warehouseId: "",
        movementType: "In",
        quantity: 1,
        sellingPrice: "",
        purchasingPrice: "",
        wholesalePrice: "",
        disCountPrice: "",
        notes: "",
      },
    };
  },

  watch: {
    search: {
      handler() {
        if (this.pageNumber !== 1) {
          this.pageNumber = 1;
          return;
        }
        this.GetAllItems();
      },
      deep: true,
    },

    pageNumber() {
      this.GetAllItems();
    },
    
    // if disCountPrice 0 make it equal to sellingPrice
    "addForm.sellingPrice": {
      handler() {
          this.addForm.disCountPrice = this.addForm.sellingPrice;
      },
      deep: true,
    },

    
  },

  mounted() {
    this.getTags();
    this.getBrands();
    this.loadWarehouses();
    this.GetAllItems();
    this.addForm.code = Math.floor(Math.random() * 1000000000).toString();
    this.userInfo = JSON.parse(localStorage.getItem("info"));
  },

  computed: {
    addWarehouseTotal() {
      return (this.warehouseStockRows || []).reduce((s, r) => s + (Number(r.quantity) || 0), 0);
    },
    editWarehouseTotal() {
      return (this.editWarehouseStockRows || []).reduce((s, r) => s + (Number(r.quantity) || 0), 0);
    },
    editRestockAddedQty() {
      const added = this.editWarehouseTotal - (Number(this.editBaselineQuantity) || 0);
      return added > 0 ? added : 0;
    },
    editShowRestockCostHint() {
      return this.editRestockAddedQty > 0;
    },
    editWeightedCostPreview() {
      if (!this.editShowRestockCostHint) return null;
      return computeWeightedAverageCost(
        this.editBaselineQuantity,
        this.editBaselinePurchasingPrice,
        this.editRestockAddedQty,
        this.editForm.purchasingPrice
      );
    },
    stockEntryWeightedPreview() {
      if (this.stockEntryForm.movementType !== "In") return null;
      const batch = this.parseOptionalPrice(this.stockEntryForm.purchasingPrice);
      if (batch == null) return null;
      const qty = Math.max(0, Number(this.stockEntryForm.quantity) || 0);
      if (qty <= 0) return null;

      let baseQty = Number(this.editBaselineQuantity) || 0;
      let baseCost = Number(this.editBaselinePurchasingPrice) || 0;
      const snap = this.stockEntryEditingSnapshot;
      if (snap && snap.movementType === "In") {
        const oldQty = Math.max(0, Number(snap.quantity) || 0);
        baseQty = Math.max(0, baseQty - oldQty);
        if (snap.batchPurchasingPrice != null && oldQty > 0) {
          const currentQty = Number(this.editBaselineQuantity) || 0;
          const currentCost = Number(this.editBaselinePurchasingPrice) || 0;
          if (baseQty <= 0) {
            baseCost = Number(snap.batchPurchasingPrice) || baseCost;
          } else {
            baseCost =
              (currentQty * currentCost - oldQty * Number(snap.batchPurchasingPrice)) / baseQty;
          }
        }
      }

      return computeWeightedAverageCost(baseQty, baseCost, qty, batch);
    },
    itemFields() {
      return [
        {
          key: 'name',
          label: this.$t('itemNamePlaceholder') || 'اسم المنتج',
          sortable: true,
          thClass: 'item-header-cell item-col-product',
          tdClass: 'item-col-product',
        },
        {
          key: 'sellingPrice',
          label: this.$t('itemPriceLabel') || 'السعر',
          sortable: true,
          thClass: 'item-header-cell item-col-price',
          tdClass: 'item-col-price',
        },
        {
          key: 'wholesalePrice',
          label: this.$t('wholesalePricePlaceholder') || 'سعر الجملة',
          sortable: true,
          thClass: 'item-header-cell item-col-price',
          tdClass: 'item-col-price',
        },
        {
          key: 'quantity',
          label: this.$t('quantityLabel') || this.$t('quantity') || 'الكمية',
          sortable: true,
          thClass: 'item-header-cell item-col-qty',
          tdClass: 'item-col-qty',
        },
        {
          key: 'expiryDate',
          label: this.$t('expiryDateLabel') || 'الصلاحية',
          sortable: true,
          thClass: 'item-header-cell item-col-expiry',
          tdClass: 'item-col-expiry',
        },
        {
          key: 'tags',
          label: this.$t('categoryPlaceholder') || 'القسم',
          sortable: true,
          thClass: 'item-header-cell item-col-tag',
          tdClass: 'item-col-tag',
        },
        {
          key: 'brand',
          label: this.$t('brandPlaceholder') || 'البراند',
          sortable: true,
          thClass: 'item-header-cell item-col-brand',
          tdClass: 'item-col-brand',
        },
        {
          key: 'actions',
          label: this.$t('actions') || this.$t('operations') || 'العمليات',
          sortable: false,
          thClass: 'item-header-cell item-col-actions',
          tdClass: 'item-col-actions',
        }
      ];
    },
    totalPages() {
      return Math.ceil(this.totalItems / this.pageSize);
    },
    itemsInStockOnPage() {
      return (this.Items || []).filter((item) => Number(item.quantity) > 0).length;
    },
    itemsOutOfStockOnPage() {
      return (this.Items || []).filter((item) => Number(item.quantity) <= 0).length;
    },
    hasActiveItemFilters() {
      return !!(
        (this.search.info && String(this.search.info).trim()) ||
        this.search.tag ||
        this.search.brandId ||
        this.search.stockStatus
      );
    },
  },

  methods: {
    productImageSrc,
    isProductImageFallback,
    onProductImageError,
    refreshPage() {
      this.GetAllItems();
    },
    getTags() {
      HTTP.get(`Admin/GetTags?pageNumber=0&pageSize=10000`)
        .then((response) => {
          this.tags = response.data.data.items;
        })
        .catch((error) => {
          this.$notify.error(this.$i18n.t("error"), {
            position: "top-right",
            timeout: 4000,
          });
        });
    },
    getBrands() {
      HTTP.get(`Admin/GetBrands?pageNumber=0&pageSize=10000`)
        .then((response) => {
          this.brands = response.data?.data?.items || [];
        })
        .catch(() => {
          this.brands = [];
        });
    },

    getFile() {
      this.$refs.uploadPhoto.click();
    },

    getFileEdit() {
      this.$refs.uploadPhotoEdit.click();
    },

    uploadFile(event) {
      const selectedFile = event.target.files[0];
      this.itemPhoto = selectedFile;
      if (selectedFile) {
        this.imagePreview = URL.createObjectURL(selectedFile);
        this.showUpload = false;
      }
    },

    uploadFileEdit(event) {
      const selectedFile = event.target.files[0];
      this.itemPhoto = selectedFile;
      if (selectedFile) {
        this.imagePreview = URL.createObjectURL(selectedFile);
        this.showUpload = false;
      }
    },

    openPrintLabelsModal(item) {
      if (!item?.code) {
        this.$notify.error(this.$t("itemCodeRequired") || "لا يوجد كود للمنتج", {
          position: "top-right",
          timeout: 2500,
        });
        return;
      }
      this.printLabelItem = item;
      this.printLabelCopies = 1;
      this.printLabelSizeId = DEFAULT_QR_LABEL_SIZE_ID;
      this.printLabelOrientation = DEFAULT_QR_LABEL_ORIENTATION;
      this.$bvModal.show("modal-printLabels");
    },
    resetPrintLabelsModal() {
      this.printLabelItem = null;
      this.printLabelCopies = 1;
      this.printLabelSizeId = DEFAULT_QR_LABEL_SIZE_ID;
      this.printLabelOrientation = DEFAULT_QR_LABEL_ORIENTATION;
    },
    formatLabelSizeOption(size) {
      return formatQrLabelSizeOption(size, (k) => this.$t(k));
    },
    confirmPrintLabels() {
      if (!this.printLabelItem?.code) return;
      const copies = Math.min(Math.max(Number(this.printLabelCopies) || 1, 1), 200);
      const price = Number(
        this.printLabelItem.disCountPrice > 0
          ? this.printLabelItem.disCountPrice
          : this.printLabelItem.sellingPrice
      );
      const currency = this.$t("currency") || "";
      const priceText =
        Number.isFinite(price) && price > 0
          ? `${price.toLocaleString("en-EG")} ${currency}`.trim()
          : "";

      const ok = printQrLabels(
        {
          code: this.printLabelItem.code,
          name: this.printLabelItem.name,
          priceText,
        },
        {
          copies,
          sizeId: this.printLabelSizeId,
          orientation: this.printLabelOrientation,
        }
      );

      if (!ok) {
        this.$notify.error(
          this.$t("printError") || "تعذرت الطباعة — اسمح بالنوافذ المنبثقة",
          { position: "top-right", timeout: 3500 }
        );
        return;
      }
      this.closeModel("modal-printLabels");
    },

    deleteItemModel(id) {
      this.itemId = id;
      this.$bvModal.show("modal-delete");
    },
    openItemCodesModal(item) {
      this.codesModalItem = item;
      this.codesModalPrimary = item?.code || "";
      this.codesModalList = [];
      this.newItemCode = "";
      this.$bvModal.show("modal-itemCodes");
      this.loadItemCodes();
    },
    resetItemCodesModal() {
      this.codesModalItem = null;
      this.codesModalPrimary = "";
      this.codesModalList = [];
      this.newItemCode = "";
      this.codesModalLoading = false;
      this.codesModalSaving = false;
      this.codesModalDeletingId = null;
    },
    mapItemCodeError(key) {
      if (key && this.$te(key)) return this.$t(key);
      return key || this.$t("error");
    },
    async loadItemCodes() {
      if (!this.codesModalItem?.id) return;
      this.codesModalLoading = true;
      try {
        const response = await HTTP.get(
          `Admin/GetItemCodes?itemId=${this.codesModalItem.id}`
        );
        const data = response?.data?.data;
        this.codesModalPrimary = data?.primaryCode || this.codesModalItem.code || "";
        this.codesModalList = Array.isArray(data?.codes) ? data.codes : [];
      } catch (error) {
        this.$notify.error(this.mapItemCodeError(error?.response?.data?.message), {
          position: "top-right",
          timeout: 3000,
          maxToasts: 1,
        });
      } finally {
        this.codesModalLoading = false;
      }
    },
    async addItemCode() {
      const code = String(this.newItemCode || "").trim();
      if (!code || !this.codesModalItem?.id || this.codesModalSaving) return;
      this.codesModalSaving = true;
      try {
        const response = await HTTP.post("Admin/AddItemCode", {
          itemId: this.codesModalItem.id,
          code,
        });
        if (response?.data?.errorStatus) {
          throw { response: { data: { message: response.data.message } } };
        }
        this.newItemCode = "";
        this.$notify.success(this.$t("itemCodeAdded") || "تمت إضافة الكود", {
          position: "top-right",
          timeout: 2500,
          maxToasts: 1,
        });
        await this.loadItemCodes();
      } catch (error) {
        this.$notify.error(this.mapItemCodeError(error?.response?.data?.message), {
          position: "top-right",
          timeout: 3500,
          maxToasts: 1,
        });
      } finally {
        this.codesModalSaving = false;
      }
    },
    async deleteItemCode(id) {
      if (!id || this.codesModalDeletingId) return;
      this.codesModalDeletingId = id;
      try {
        const response = await HTTP.delete(`Admin/DeleteItemCode?id=${id}`);
        if (response?.data?.errorStatus) {
          throw { response: { data: { message: response.data.message } } };
        }
        this.$notify.success(this.$t("itemCodeDeleted") || "تم حذف الكود", {
          position: "top-right",
          timeout: 2500,
          maxToasts: 1,
        });
        await this.loadItemCodes();
      } catch (error) {
        this.$notify.error(this.mapItemCodeError(error?.response?.data?.message), {
          position: "top-right",
          timeout: 3500,
          maxToasts: 1,
        });
      } finally {
        this.codesModalDeletingId = null;
      }
    },
    async loadWarehouses() {
      try {
        const res = await HTTP.get("Warehouses/ForPos");
        this.warehouses = (res.data?.data || []).map((w) => ({
          id: w.id,
          name: w.name,
          isDefault: w.isDefault,
          isActive: true,
        }));
        this.resetAddWarehouseRows();
      } catch (_) {
        this.warehouses = [];
        this.warehouseStockRows = [];
      }
    },
    resetAddWarehouseRows() {
      this.warehouseStockRows = (this.warehouses || []).map((w) => ({
        warehouseId: w.id,
        warehouseName: w.name,
        quantity: w.isDefault ? Number(this.addForm.quantity) || 0 : 0,
        lowStockAlertQuantity: "",
      }));
    },
    normalizeWarehouseAlert(value) {
      if (value === null || value === undefined || String(value).trim() === "") {
        return null;
      }
      const n = Number(value);
      return Number.isFinite(n) && n >= 0 ? n : null;
    },
    buildWarehouseStocksJson(rows) {
      if (!rows || !rows.length) return null;
      return JSON.stringify(
        rows.map((r) => ({
          warehouseId: r.warehouseId,
          quantity: Math.max(0, Number(r.quantity) || 0),
          lowStockAlertQuantity: this.normalizeWarehouseAlert(r.lowStockAlertQuantity),
        }))
      );
    },
    getItemInfo(item) {
      this.itemPhoto = null;
      this.itemImage = item.image || "";
      this.imagePreview = "";
      this.editForm = {
        id: item.id,
        name: item.name || "",
        description: item.description || "",
        sellingPrice: item.sellingPrice || 0,
        purchasingPrice: item.purchasingPrice || 0,
        disCountPrice: item.disCountPrice || 0,
        wholesalePrice: item.wholesalePrice || 0,
        tags: item.tags || "مواد اخرى",
        brandId:
          item.brandId != null && item.brandId !== undefined
            ? String(item.brandId)
            : item.brand?.id != null
              ? String(item.brand.id)
              : "",
        code: item.code || "",
        quantity: item.quantity || 0,
        lowStockAlertQuantity:
          item.lowStockAlertQuantity ?? item.LowStockAlertQuantity ?? "",
        expiryDate: this.toDateInputValue(item.expiryDate ?? item.ExpiryDate),
      };
      this.editBaselineQuantity = Number(item.quantity) || 0;
      this.editBaselinePurchasingPrice = Number(item.purchasingPrice) || 0;
      const stocks = item.warehouseStocks || item.WarehouseStocks || [];
      const legacyAlert =
        item.lowStockAlertQuantity ?? item.LowStockAlertQuantity ?? "";
      if (stocks.length) {
        this.editWarehouseStockRows = stocks.map((s) => {
          const alert =
            s.lowStockAlertQuantity ??
            s.LowStockAlertQuantity ??
            (s.isDefault || s.IsDefault ? legacyAlert : "");
          return {
            warehouseId: s.warehouseId ?? s.WarehouseId,
            warehouseName: s.warehouseName ?? s.WarehouseName,
            quantity: Number(s.quantity ?? s.Quantity) || 0,
            lowStockAlertQuantity:
              alert === null || alert === undefined ? "" : alert,
          };
        });
      } else {
        this.editWarehouseStockRows = (this.warehouses || []).map((w) => ({
          warehouseId: w.id,
          warehouseName: w.name,
          quantity: w.isDefault ? Number(item.quantity) || 0 : 0,
          lowStockAlertQuantity: w.isDefault ? legacyAlert : "",
        }));
      }
      if (this.editWarehouseStockRows.length) {
        this.editBaselineQuantity = this.editWarehouseStockRows.reduce(
          (s, r) => s + (Number(r.quantity) || 0),
          0
        );
      }
      this.resetStockEntryForm();
      this.loadStockEntries(item.id);
      this.$bvModal.show("modal-editItem");
    },
    resetStockEntryForm() {
      const defaultWh =
        (this.warehouses || []).find((w) => w.isDefault) || (this.warehouses || [])[0];
      this.stockEntryEditingId = null;
      this.stockEntryEditingSnapshot = null;
      this.stockEntryForm = {
        warehouseId: defaultWh ? String(defaultWh.id) : "",
        movementType: "In",
        quantity: 1,
        sellingPrice: "",
        purchasingPrice: "",
        wholesalePrice: "",
        disCountPrice: "",
        notes: "",
      };
    },
    parseOptionalPrice(value) {
      if (value === null || value === undefined || String(value).trim() === "") {
        return null;
      }
      const n = Number(value);
      return Number.isFinite(n) ? n : null;
    },
    async loadStockEntries(itemId) {
      if (!itemId) {
        this.stockEntries = [];
        return;
      }
      this.stockEntriesLoading = true;
      try {
        const res = await HTTP.get("Admin/GetItemStockEntries", {
          params: { itemId },
        });
        const rows = res?.data?.data || [];
        this.stockEntries = rows.map((r) => ({
          id: r.id ?? r.Id,
          insertDate: r.insertDate ?? r.InsertDate,
          movementType: r.movementType ?? r.MovementType,
          quantity: r.quantity ?? r.Quantity,
          warehouseId: r.warehouseId ?? r.WarehouseId,
          warehouseName: r.warehouseName ?? r.WarehouseName,
          purchasingPrice: r.purchasingPrice ?? r.PurchasingPrice,
          sellingPrice: r.sellingPrice ?? r.SellingPrice,
          wholesalePrice: r.wholesalePrice ?? r.WholesalePrice,
          disCountPrice: r.disCountPrice ?? r.DisCountPrice,
          batchPurchasingPrice: r.batchPurchasingPrice ?? r.BatchPurchasingPrice ?? null,
          notes: r.notes ?? r.Notes,
        }));
      } catch (_) {
        this.stockEntries = [];
      } finally {
        this.stockEntriesLoading = false;
      }
    },
    formatStockEntryDate(value) {
      if (!value) return "—";
      try {
        return new Intl.DateTimeFormat(this.$i18n.locale === "ar" ? "ar-IQ" : "en-GB", {
          dateStyle: "short",
          timeStyle: "short",
          timeZone: BUSINESS_TIME_ZONE,
          numberingSystem: "latn",
        }).format(new Date(value));
      } catch (_) {
        return String(value);
      }
    },
    formatStockEntryNotes(notes) {
      if (!notes) return "—";
      if (notes === "openingBalance") {
        return this.$t("openingBalanceNote") || "رصيد افتتاحي";
      }
      return notes;
    },
    /** Batch unit cost entered for this In row; falls back to WA cost snapshot. */
    stockEntryPurchaseDisplay(row) {
      if (!row) return 0;
      if (row.batchPurchasingPrice != null && row.batchPurchasingPrice !== "") {
        return Number(row.batchPurchasingPrice);
      }
      return Number(row.purchasingPrice) || 0;
    },
    startEditStockEntry(row) {
      if (!row || !row.id) return;
      this.stockEntryEditingId = row.id;
      this.stockEntryEditingSnapshot = {
        movementType: row.movementType,
        quantity: row.quantity,
        batchPurchasingPrice: row.batchPurchasingPrice,
      };
      const notes =
        row.notes === "openingBalance"
          ? this.$t("openingBalanceNote") || "رصيد افتتاحي"
          : row.notes || "";
      this.stockEntryForm = {
        warehouseId: row.warehouseId != null ? String(row.warehouseId) : "",
        movementType: row.movementType === "Out" ? "Out" : "In",
        quantity: Number(row.quantity) || 1,
        sellingPrice:
          row.movementType === "In" && row.sellingPrice != null ? String(row.sellingPrice) : "",
        purchasingPrice:
          row.movementType === "In" && row.batchPurchasingPrice != null
            ? String(row.batchPurchasingPrice)
            : "",
        wholesalePrice:
          row.movementType === "In" && row.wholesalePrice != null ? String(row.wholesalePrice) : "",
        disCountPrice:
          row.movementType === "In" && row.disCountPrice != null ? String(row.disCountPrice) : "",
        notes,
      };
      const formEl = this.$el?.querySelector?.(".item-stock-entry-form");
      if (formEl && formEl.scrollIntoView) {
        formEl.scrollIntoView({ behavior: "smooth", block: "nearest" });
      }
    },
    cancelEditStockEntry() {
      this.resetStockEntryForm();
    },
    async deleteStockEntry(row) {
      if (!row?.id || this.stockEntrySaving) return;
      const ok = await this.$confirm({
        title: this.$t("confirmDelete") || "تأكيد المسح",
        message:
          this.$t("itemStockEntryDeleteConfirm") ||
          "هل تريد مسح هذه الحركة من السجل؟ سيتم عكس تأثيرها على الكمية وسعر التكلفة إن وُجد.",
        confirmText: this.$t("delete") || "مسح",
        cancelText: this.$t("cancel") || "إلغاء",
        variant: "danger",
      });
      if (!ok) return;

      this.stockEntrySaving = true;
      try {
        const res = await HTTP.delete(`Admin/DeleteItemStockEntry?id=${row.id}`);
        if (res?.data?.errorStatus) {
          const msg = res.data.message;
          this.$notify.error(
            msg && this.$te(msg) ? this.$t(msg) : msg || this.$t("itemStockEntryDeleteFailed")
          );
          return;
        }

        if (this.stockEntryEditingId === row.id) {
          this.resetStockEntryForm();
        }

        const item = res?.data?.data?.item;
        if (item) {
          this.applyItemAfterStockEntry(item);
        }
        await this.loadStockEntries(this.editForm.id);
        this.GetAllItems();
        this.$notify.success(this.$t("itemStockEntryDeleted") || "تم مسح الحركة");
      } catch (err) {
        const msg = err?.response?.data?.message;
        this.$notify.error(
          msg && this.$te(msg)
            ? this.$t(msg)
            : msg || this.$t("itemStockEntryDeleteFailed") || "فشل مسح الحركة"
        );
      } finally {
        this.stockEntrySaving = false;
      }
    },
    async submitStockEntry() {
      if (!this.editForm.id || this.stockEntrySaving) return;
      const qty = Math.floor(Number(this.stockEntryForm.quantity) || 0);
      if (qty <= 0) {
        this.$notify.error(this.$t("itemStockEntryInvalidQty") || "أدخل كمية صحيحة");
        return;
      }
      if (!this.stockEntryForm.warehouseId) {
        this.$notify.error(this.$t("itemStockEntrySelectWarehouse") || "اختر المخزن");
        return;
      }

      const payload = {
        itemId: Number(this.editForm.id),
        warehouseId: Number(this.stockEntryForm.warehouseId),
        movementType: this.stockEntryForm.movementType,
        quantity: qty,
        notes: this.stockEntryForm.notes || null,
      };

      // Keep opening-balance marker if user left the localized label
      const openingLabel = this.$t("openingBalanceNote") || "رصيد افتتاحي";
      if (
        this.stockEntryEditingId &&
        this.stockEntries.find((e) => e.id === this.stockEntryEditingId)?.notes === "openingBalance" &&
        (payload.notes === openingLabel || payload.notes === "openingBalance")
      ) {
        payload.notes = "openingBalance";
      }

      if (this.stockEntryForm.movementType === "In") {
        payload.sellingPrice = this.parseOptionalPrice(this.stockEntryForm.sellingPrice);
        payload.purchasingPrice = this.parseOptionalPrice(this.stockEntryForm.purchasingPrice);
        payload.wholesalePrice = this.parseOptionalPrice(this.stockEntryForm.wholesalePrice);
        payload.disCountPrice = this.parseOptionalPrice(this.stockEntryForm.disCountPrice);
      }

      this.stockEntrySaving = true;
      try {
        const editingId = this.stockEntryEditingId;
        const res = editingId
          ? await HTTP.put(`Admin/UpdateItemStockEntry?id=${editingId}`, payload)
          : await HTTP.post("Admin/AddItemStockEntry", payload);
        if (res?.data?.errorStatus) {
          const msg = res.data.message;
          this.$notify.error(
            msg && this.$te(msg) ? this.$t(msg) : msg || this.$t("itemStockEntryFailed")
          );
          return;
        }

        const item = res?.data?.data?.item;
        if (item) {
          this.applyItemAfterStockEntry(item);
        }
        await this.loadStockEntries(this.editForm.id);
        this.resetStockEntryForm();
        this.GetAllItems();
        this.$notify.success(
          editingId
            ? this.$t("itemStockEntryUpdated") || "تم تعديل الحركة"
            : this.$t("itemStockEntrySaved") || "تم حفظ الحركة"
        );
      } catch (err) {
        const msg = err?.response?.data?.message;
        this.$notify.error(
          msg && this.$te(msg) ? this.$t(msg) : msg || this.$t("itemStockEntryFailed") || "فشل حفظ الحركة"
        );
      } finally {
        this.stockEntrySaving = false;
      }
    },
    applyItemAfterStockEntry(item) {
      this.editForm.sellingPrice = item.sellingPrice ?? item.SellingPrice ?? this.editForm.sellingPrice;
      this.editForm.purchasingPrice =
        item.purchasingPrice ?? item.PurchasingPrice ?? this.editForm.purchasingPrice;
      this.editForm.wholesalePrice =
        item.wholesalePrice ?? item.WholesalePrice ?? this.editForm.wholesalePrice;
      this.editForm.disCountPrice =
        item.disCountPrice ?? item.DisCountPrice ?? this.editForm.disCountPrice;
      this.editForm.quantity = item.quantity ?? item.Quantity ?? this.editForm.quantity;
      this.editBaselineQuantity = Number(this.editForm.quantity) || 0;
      this.editBaselinePurchasingPrice = Number(this.editForm.purchasingPrice) || 0;

      const stocks = item.warehouseStocks || item.WarehouseStocks || [];
      if (stocks.length) {
        this.editWarehouseStockRows = stocks.map((s) => ({
          warehouseId: s.warehouseId ?? s.WarehouseId,
          warehouseName: s.warehouseName ?? s.WarehouseName,
          quantity: Number(s.quantity ?? s.Quantity) || 0,
          lowStockAlertQuantity:
            s.lowStockAlertQuantity ?? s.LowStockAlertQuantity ?? "",
        }));
        this.editBaselineQuantity = this.editWarehouseStockRows.reduce(
          (sum, r) => sum + (Number(r.quantity) || 0),
          0
        );
      }
    },
    formatMoney(value) {
      return formatMoneyLatn(value);
    },
    addItem() {
      this.show = true;
      var formData = new FormData();
      formData.append("Name", this.addForm.name);
      formData.append("Description", this.addForm.description);
      formData.append("SellingPrice", this.addForm.sellingPrice);
      formData.append("PurchasingPrice", this.addForm.purchasingPrice);
      formData.append("Tags", this.addForm.tags);
      formData.append("BrandId", this.addForm.brandId || "");
      formData.append("Code", this.addForm.code);
      formData.append("Image", this.itemPhoto);
      formData.append("DisCountPrice", this.addForm.disCountPrice);
      formData.append("WholesalePrice", this.addForm.wholesalePrice);
      const totalQty = this.warehouseStockRows.length
        ? this.addWarehouseTotal
        : this.addForm.quantity;
      formData.append("Quantity", totalQty);
      const stocksJson = this.buildWarehouseStocksJson(this.warehouseStockRows);
      if (stocksJson) {
        formData.append("WarehouseStocksJson", stocksJson);
      } else {
        this.appendLowStockAlertQuantity(formData, this.addForm.lowStockAlertQuantity);
      }
      this.appendExpiryDate(formData, this.addForm.expiryDate);

      HTTP.post(`Admin/AddItem`, formData)
