            closeOnClick: true,
            pauseOnFocusLoss: true,
            pauseOnHover: true,
            draggable: true,
            draggablePercent: 0.6,
            showCloseButtonOnHover: false,
            hideProgressBar: true,
            closeButton: "button",
            icon: true,
          });
          this.addForm.name = "";
          this.addForm.description = "";
          this.addForm.sellingPrice = 0;
          this.addForm.purchasingPrice = 0;
          this.addForm.code = Math.floor(
            Math.random() * 1000000000000
          ).toString();
          this.addForm.disCountPrice = 0;
          this.addForm.wholesalePrice = 0;
          this.addForm.quantity = 0;
          this.addForm.lowStockAlertQuantity = "";
          this.addForm.expiryDate = "";
          this.addForm.brandId = "";
          this.resetAddWarehouseRows();
          this.imagePreview = "";
          this.itemPhoto = null;
