      HTTP.delete(`Admin/DeleteItem?id=${this.itemId}`)
        .then((response) => {
          this.show = false;
          this.$notify.success(this.$i18n.t("somethingWrong"), {
            position: "top-right",
            timeout: 4000,
            closeOnClick: true,
            pauseOnFocusLoss: true,
            pauseOnHover: true,
            draggable: true,
            draggablePercent: 0.6,
            showCloseButtonOnHover: false,
            hideProgressBar: true,
            closeButton: "button",
            icon: true,
          });
          this.GetAllItems();
          this.$bvModal.hide(modelId);
        })
        .catch((error) => {
          this.show = false;
          this.$notify.error(this.$i18n.t("somethingWrong"), {
            position: "top-right",
            timeout: 4000,
            closeOnClick: true,
            pauseOnFocusLoss: true,
            pauseOnHover: true,
            draggable: true,
            draggablePercent: 0.6,
            showCloseButtonOnHover: false,
            hideProgressBar: true,
            closeButton: "button",
            icon: true,
          });
        });
    },

    formatPrice(price) {
      return formatMoneyLatn(price);
    },
    formatQuantity(quantity) {
      return formatMoneyLatn(quantity, { maximumFractionDigits: 0 });
    },
    getLowStockAlertThreshold(item) {
      const raw = item?.lowStockAlertQuantity ?? item?.LowStockAlertQuantity;
      if (raw === null || raw === undefined || raw === "") return null;
      const n = Number(raw);
      return Number.isFinite(n) ? n : null;
    },
    isStockAlertActive(item) {
      const stocks = item?.warehouseStocks || item?.WarehouseStocks || [];
      if (stocks.length) {
        return stocks.some((s) => {
          const alert = s.lowStockAlertQuantity ?? s.LowStockAlertQuantity;
          if (alert === null || alert === undefined || alert === "") return false;
          const t = Number(alert);
          if (!Number.isFinite(t)) return false;
          return Number(s.quantity ?? s.Quantity) <= t;
        });
      }
      const threshold = this.getLowStockAlertThreshold(item);
      if (threshold === null) return false;
      return Number(item?.quantity) <= threshold;
    },
    quantityCellClass(item) {
      if (Number(item?.quantity) <= 0) return "item-quantity-text--low";
      if (this.isStockAlertActive(item)) return "item-quantity-text--alert";
      return "";
    },
    appendLowStockAlertQuantity(formData, value, force = false) {
      const isEmpty = value === null || value === undefined || String(value).trim() === "";
      if (force) {
        formData.append("LowStockAlertQuantity", isEmpty ? "" : String(value));
        return;
      }
      if (!isEmpty) {
        formData.append("LowStockAlertQuantity", value);
      }
    },
    appendExpiryDate(formData, value, force = false) {
      const isEmpty = value === null || value === undefined || String(value).trim() === "";
      if (force) {
        formData.append("ExpiryDate", isEmpty ? "" : String(value).trim());
        return;
      }
      if (!isEmpty) {
        formData.append("ExpiryDate", String(value).trim());
      }
    },
    toDateInputValue(value) {
      if (value == null || value === "") return "";
      const s = String(value);
      if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
      const d = new Date(s);
      if (Number.isNaN(d.getTime())) return "";
      const yyyy = d.getFullYear();
      const mm = String(d.getMonth() + 1).padStart(2, "0");
      const dd = String(d.getDate()).padStart(2, "0");
      return `${yyyy}-${mm}-${dd}`;
    },
    formatItemExpiryDate(value) {
      const v = this.toDateInputValue(value);
      return v || "—";
    },
    expiryDaysRemaining(value) {
      const v = this.toDateInputValue(value);
      if (!v) return null;
      const parts = new Intl.DateTimeFormat("en-CA", {
        timeZone: BUSINESS_TIME_ZONE,
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
      }).formatToParts(new Date());
      const get = (type) => parts.find((p) => p.type === type)?.value || "";
      const todayStr = `${get("year")}-${get("month")}-${get("day")}`;
      const today = new Date(`${todayStr}T00:00:00`);
      const expiry = new Date(`${v}T00:00:00`);
      if (Number.isNaN(today.getTime()) || Number.isNaN(expiry.getTime())) return null;
      return Math.round((expiry.getTime() - today.getTime()) / 86400000);
    },
    expiryCellClass(item) {
      const days = this.expiryDaysRemaining(item?.expiryDate ?? item?.ExpiryDate);
      if (days == null) return "item-expiry-badge--empty";
      if (days < 0) return "item-expiry-badge--expired";
      if (days <= 7) return "item-expiry-badge--soon";
      return "";
    },
    closeModel(id) {
      this.$bvModal.hide(id);
      if (id === 'modal-editItem') {
        this.imagePreview = "";
        this.itemImage = "";
        this.itemPhoto = null;
      }
    },

    GetAllItems() {
      this.show = true;
      const params = new URLSearchParams();
      params.append("pageNumber", String(this.pageNumber - 1));
      params.append("pageSize", String(this.pageSize));
      const info = String(this.search.info || "").trim();
      if (info) params.append("info", info);
      if (this.search.tag) params.append("tag", this.search.tag);
      if (this.search.brandId) params.append("brandId", this.search.brandId);
      if (this.search.stockStatus) params.append("stockStatus", this.search.stockStatus);

      HTTP.get(`Admin/GetItems?${params.toString()}`)
        .then((response) => {
          this.Items = response.data.data.items.map(item => ({
            ...item,
            imageError: false
          }));
          this.totalItems = response.data.data.totalItems;
          this.show = false;
        })
        .catch((error) => {
          this.show = false;
        });
    },
    clearItemFilters() {
      this.search = {
        info: "",
        tag: "",
        brandId: "",
        stockStatus: "",
      };
    },
    onPageChange(page) {
      this.pageNumber = page;
      this.GetAllItems();
    },
    clearImportFile() {
      this.importFile = null;
      this.importFileName = "";
      this.importResult = null;
      if (this.$refs.importFileInput) {
        this.$refs.importFileInput.value = "";
      }
    },
    onImportFileSelected(event) {
      const file = event.target.files?.[0];
      this.importFile = file || null;
      this.importFileName = file?.name || "";
      this.importResult = null;
    },
    mapImportError(key) {
      if (key && this.$te(key)) return this.$t(key);
      return key || this.$t("error");
    },
    closeImportModal() {
      this.$bvModal.hide("modal-importItems");
      this.resetImportState();
    },
    resetImportState() {
      this.importFile = null;
      this.importFileName = "";
      this.importResult = null;
      this.importUploading = false;
      if (this.$refs.importFileInput) {
        this.$refs.importFileInput.value = "";
      }
    },
    async uploadImportFile() {
      if (!this.importFile || this.importUploading) return;

      this.importUploading = true;
      this.importResult = null;

      const formData = new FormData();
      formData.append("file", this.importFile);

      try {
        const response = await HTTP.post("Admin/ImportItems", formData, {
          headers: { "Content-Type": "multipart/form-data" },
          timeout: 120000,
        });
        const payload = response?.data;
        this.importResult = payload?.data || null;

        this.$notify.success(
          this.$te(payload?.message) ? this.$t(payload.message) : this.$t("importItemsSuccess"),
          { position: "top-right", timeout: 4000, maxToasts: 1 }
        );
        this.GetAllItems();
        this.getTags();
        this.getBrands();
      } catch (error) {
        const msg = error?.response?.data?.message;
        this.$notify.error(this.mapImportError(msg) || this.$t("importItemsFailed"), {
          position: "top-right",
          timeout: 4000,
          maxToasts: 1,
        });
      } finally {
        this.importUploading = false;
      }
    },
  },
};
</script>

